/*Table structure for table `divination_card_association` */

DROP TABLE IF EXISTS `divination_card_association`;

CREATE TABLE `divination_card_association` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `tarot_record_id` int unsigned NOT NULL COMMENT '占卜记录ID（关联tarot_record表）',
  `card_id` int unsigned NOT NULL COMMENT '塔罗牌ID（关联tarot_card表）',
  `position` int NOT NULL COMMENT '牌在牌阵中的位置（如1、2、3）',
  PRIMARY KEY (`id`),
  KEY `fk_spread_card_spread` (`tarot_record_id`),
  KEY `fk_spread_card_card` (`card_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='占卜-牌关联表';

/*Data for the table `divination_card_association` */

/*Table structure for table `tarot_array_type` */

DROP TABLE IF EXISTS `tarot_array_type`;

CREATE TABLE `tarot_array_type` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '牌阵ID（主键）',
  `name` varchar(50) NOT NULL COMMENT '牌阵名称（如：三牌阵）',
  `card_count` int NOT NULL COMMENT '该牌阵需要的牌数',
  `description` varchar(200) DEFAULT '' COMMENT '牌阵说明',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='牌阵类型表';

/*Data for the table `tarot_array_type` */

