(4,'二选一牌阵',5,''),
(5,'单牌阵',1,'');

/*Table structure for table `tarot_card` */

DROP TABLE IF EXISTS `tarot_card`;

CREATE TABLE `tarot_card` (
  `id` int NOT NULL,
  `name` varchar(50) NOT NULL COMMENT '牌名（如：愚人）',
  `orientation` tinyint unsigned NOT NULL COMMENT '0:正位, 1:逆位',
  `image_url` varchar(255) NOT NULL COMMENT '牌面图片URL',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '牌的描述',
  `name_type` int DEFAULT NULL COMMENT '牌的分类：1.大阿卡那，2.权杖系列，3.圣杯系列，4.宝剑系列，5.钱币系列',
  `meaning_up` text COMMENT '正位含义',
  `meaning_rev` text COMMENT '逆位含义'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='塔罗牌基础信息表';

/*Data for the table `tarot_card` */

(0,'愚人',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/愚人 The Fool.jpg','愚者\r\n愚者象征着全新的开始与无限可能，代表踏上未知旅程的勇气。正位时展现天真烂漫的冒险精神，逆位则警示盲目乐观带来的风险。这张牌描绘着站在悬崖边却依然仰望星空的旅人，手中的白玫瑰象征纯洁初心，肩上的行囊装载人生经验。\r\n\r\n关键词\r\n新起点、自由精神、无限潜力、冒险勇气、率真本性\r\n\r\n\r\n象征意义\r\n愚者牌面通常描绘年轻旅人站在悬崖边缘，手持象征纯真与潜力的白玫瑰，肩扛代表人生经验的行囊。脚下的小狗提醒注意现实危险，而背景的旭日象征新开始。服装色彩鲜艳暗示丰富可能性，未系紧的鞋带代表不拘小节。山峦象征待征服的挑战，行囊中的权杖代表未开发的潜力。整体构图采用动态对角线，强调前进的动能。悬崖下的云雾暗示未知领域，腰间的羽毛装饰象征精神自由。\r\n\r\n原型\r\n天真者、流浪旅人、自由灵魂、冒险先驱、未琢之玉',1,'正位的愚者象征着人生新阶段的开启，鼓励以开放心态拥抱未知。代表跳出舒适圈的勇气，相信直觉而非逻辑的处世态度。提醒保持初心，在冒险中积累人生经验。正位时可能预示旅行、跳槽、创业等重大改变，强调过程比结果更重要的人生哲学。这张牌鼓励突破传统框架，以孩童般的好奇心探索世界。','逆位含义\r\n逆位的愚者警示可能陷入盲目乐观或不计后果的冒险。暗示缺乏风险评估，容易因冲动决策导致损失。可能表现为逃避现实责任，用天真态度处理复杂问题。逆位时需注意可能错失重要细节，或在关键时刻缺乏必要准备。也可能反映心理上的不成熟，需要建立更实际的规划。提醒在保持开放心态的同时，需兼顾现实基础。'),
(1,'魔术师',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/魔术师 The Magician.jpg','正位的魔术师象征着强大的意志力与创造力，手持法器连接天地能量，桌上四元素齐备展现资源整合能力。逆位时法器指向地面，能量流失暗示才能的误用或沟通障碍。牌面充满红色与白色象征热情与纯洁的平衡，黄色背景代表智慧的光芒。\r\n\r\n关键词\r\n创造力、资源整合、意志力、有效沟通、显化能力\r\n\r\n\r\n象征意义\r\n牌面中央站立的魔术师右手高举权杖引动天界能量，左手下指将力量导入物质世界。白色长袍象征纯洁动机，红色披风代表行动热情。腰间无限符号暗示永恒的生命力与无限可能性。桌上四元素器具：圣杯（水元素情感）、宝剑（风元素思想）、钱币（土元素物质）、权杖（火元素行动）的完整陈列，显示对现实世界的全面掌控能力。头顶的横向8字符号（∞）与玫瑰花藤构成能量循环系统，黄色背景中的智慧之光笼罩整个场景。脚下百合与玫瑰交织，平衡精神追求与世俗欲望。\r\n\r\n原型\r\n创造者、沟通者、转化者、仪式大师、现实建筑师',1,'正位的魔术师展现将想法转化为现实的非凡能力。右手权杖指天汇聚宇宙能量，左手引导至物质领域，象征天地人的完美协调。桌上摆放的圣杯、宝剑、钱币和权杖代表四元素的完整掌控，表明已具备实现目标所需全部资源。红玫瑰与白百合的缠绕象征热情与理智的平衡，无限符号腰带暗示潜能的无限性。此时是采取行动的最佳时机，清晰的思维与精准的表达能力可使任何计划成功启动。\r\n','逆位的魔术师揭示能量通道的阻塞。法器失去连接天地的功能，象征才能的滥用或沟通失效。四元素散落暗示资源管理失当，可能出现设备故障或信息误传。红色长袍褪色表示热情减退，无限符号断裂反映自我怀疑。可能遭遇技术问题、承诺无法兑现或创意被剽窃。此时需检视是否过度依赖技巧而忽视本质，或陷入华而不实的自我推销。逆位也提示重新学习基础技能的必要性。'),
(2,'女祭司',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/女祭司 The High Priestess.jpg','正位的女祭司象征深层的直觉与神秘智慧，端坐于黑白柱之间手持托拉卷轴，脚下新月代表潜意识力量。逆位时帷幕后的水面泛起涟漪，暗示隐藏真相的泄露或直觉混乱。作为神谕的守护者，她连接着可见与不可见的世界。\r\n\r\n关键词\r\n直觉、神秘知识、潜意识、静观、灵性觉醒\r\n\r\n象征意义\r\n画面中央的女祭司身着蓝白长袍象征纯洁与神性，头戴三重冠冕代表身心灵三位一体。黑白柱上的B与J字母对应二元对立与神殿入口，中间帷幕的棕榈与石榴图案暗示生命循环。手持的托拉卷轴只显露部分文字，象征未完全揭示的奥秘。脚下的新月连接潮汐与潜意识波动，背后平静水面下暗藏智慧之泉。整个画面构成神圣知识的圣殿，邀请探索可见世界背后的永恒真理。\r\n\r\n原型\r\n神秘守護者、直覺先知、靈性媒介、奧秘保管者、靜默觀察者',1,'正位的女祭司揭示潜意识的宝库，象征直觉超越逻辑的智慧。当这张牌出现时，暗示需要倾听内在声音而非依赖表面信息。黑白柱代表二元性的平衡，卷轴中的未展开知识提醒我们有些真理需要时机成熟才能显现。新月连接着女性周期与潜意识波动，建议通过冥想或梦境获取指引。作为灵性守门人，她要求我们在行动前保持静观与内在反思。\r\n','逆位的女祭司暗示直觉通道受阻，可能因过度理性压抑内在声音，或重要信息被刻意隐瞒。帷幕的破损象征秘密泄露的风险，水面涟漪预示情绪干扰判断。此时需警惕表面平静下的暗流，可能错失灵性讯号或误解梦境象征。建议重新建立与潜意识的连接，检视是否忽视内在警告，或过度自我保护导致信息屏蔽。有时也反映灵性成长的停滞期。'),
(3,'女皇',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/女皇 The Empress.jpg','女皇牌象征丰饶与母性力量，端坐于自然宝座之上手持权杖，孕育万物的女神形象。她代表着物质世界的丰盛、感官享受和创造性潜能，是生命孕育与自然循环的具象化表现。\r\n\r\n关键词\r\n丰饶、母性、创造力、感官享受、自然循环\r\n\r\n象征意义\r\n女皇身着丰饶长袍端坐于绣满石榴纹样的宝座，手持象征生命力的榭寄生权杖。宝座旁的麦穗与身后瀑布象征生生不息的生命循环，脚下新月代表女性神秘力量。心形靠垫上的金星符号将爱与美神维纳斯能量注入物质世界，腹部微微隆起暗示孕育中的新生命。整个画面充满自然元素，强调创造力与物质丰盛的深层联系。\r\n\r\n原型\r\n母亲、丰饶女神、自然守护者、创造之源、感官导师',1,'正位的女皇象征着生命丰盛的季节，如同孕育万物的母亲大地。她提醒我们要与自然和谐共处，拥抱感官体验并信任创造过程。在事业中预示新项目的萌芽，在感情中代表稳定发展的关系，在健康方面强调身心滋养的重要性。这张牌鼓励通过艺术创作或亲近自然来激活内在生命力，同时提醒保持慷慨与包容的母性特质。\r\n','逆位的女皇可能暗示过度沉溺物质享受导致资源浪费，或母性能量失衡造成的控制欲。创造力可能因自我怀疑而受阻，人际关系可能出现过度依赖或情感勒索。在健康方面需注意饮食失调或生殖系统问题，环境方面警示对自然资源的滥用。此时需要重新平衡给予与接受的关系，建立健康的自我边界。'),
(4,'皇帝',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/皇帝 The Emperor.jpg','皇帝牌体现结构化权威与世俗权力，威严端坐于石制王座手持权杖与十字球。象征社会秩序的确立、理性思维的统治以及父权体系的运作，代表着通过纪律与策略实现的稳定统治。\r\n\r\n关键词\r\n权威、秩序、纪律、领导力、战略规划\r\n\r\n\r\n象征意义\r\n皇帝身披铠甲端坐于立方体石制王座，右手持古埃及十字权杖象征生命统治权，左手握十字球体代表世俗支配。王座扶手雕刻公羊头彰显白羊座的行动魄力，背后山脉象征不可动摇的权威。脚下流淌的河流被规整为直线渠道，体现将自然力量转化为文明秩序的能力。红色长袍与铠甲的金色纹饰形成权力美学的视觉语言，强调理性对混沌的征服。\r\n\r\n原型\r\n统治者、战略家、纪律执行者、体系构建者、父权象征',1,'正位的皇帝象征着社会结构的稳固与理性统治的力量。他代表着通过明确规则和有效管理实现的长期稳定，在事业中预示制度化的成功，在人际关系中强调责任与承诺。这张牌鼓励建立清晰的边界与可执行的计划，提醒需要平衡权威与同理心。当面对复杂局面时，皇帝能量教导我们运用逻辑分析而非情感冲动，通过建立可靠系统来保障目标的实现。','逆位的皇帝警示权力失衡带来的危机，可能表现为独断专行或官僚主义僵化。过度控制欲会扼杀创造力，教条主义导致适应力下降。在家庭中可能反映父权压迫，在组织中暗示管理失效。此时需要审视规则的必要性，培养灵活性，同时警惕权力寻租或责任逃避。逆位皇帝也提示需修复与父亲/权威人物的关系，重建健康的权力动态。'),
(5,'聖職者',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/聖職者 The Hierophant.jpg','聖職者牌象征传统智慧与精神权威，端坐于宗教圣殿手持三重权杖。代表着制度化的信仰体系、道德规范的传承以及集体意识的引导，是连接神圣法则与世俗社会的精神桥梁。\r\n\r\n关键词\r\n传统、仪式、道德准则、精神指导、社会规范\r\n\r\n象征意义\r\n聖職者头戴三重冠冕端坐于两柱之间的圣座，右手作祝福手势左手持三重十字权杖。脚下两把交叉钥匙象征开启精神与物质世界的大门，信徒们分列两侧接受教化。宝座上的公牛与大象浮雕代表稳固的精神基础，经卷与权杖上的纹饰暗示秘传知识的传承。彩色玻璃投射的光线形成神圣几何图案，营造出制度性宗教的庄严氛围。\r\n\r\n原型\r\n精神导师、传统守护者、仪式主持者、道德仲裁者、秘传知识保管者',1,'正位的聖職者代表着文化传承与精神共同体的维系。他象征着通过仪式和教导传递的集体智慧，在人生抉择时提示遵循传统价值体系。在学业中强调系统化学习的重要性，在婚姻中体现社会认可的结合形式。这张牌鼓励参与社群活动并尊重既有知识体系，同时也提醒保持开放心态吸收不同文化精髓。当需要道德指引时，教皇能量提供经过时间检验的解决方案。','逆位的聖職者警示僵化的教条对个人成长的限制，可能表现为盲目遵循传统或权威崇拜。精神层面可能出现信仰体系动摇，社会关系中或遭遇形式主义的束缚。此时需要突破思维定式，重新评估既有规范的价值。逆位也暗示某些权威人士可能滥用影响力，提醒保持独立思考并建立个人化的价值体系。'),
(6,'恋人',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/恋人 The Lovers.jpg','恋人牌展现人类面对终极选择的精神图景，亚当夏娃在天使祝福下立于生命之树两侧。象征着灵魂共鸣的吸引、道德抉择的考验以及阴阳能量的完美调和，揭示真爱与自由意志的深刻关联。\r\n\r\n关键词\r\n爱情联结、重大抉择、灵魂共鸣、阴阳调和、道德考验\r\n\r\n\r\n象征意义\r\n画面中央天使拉斐尔展开火焰之翼，手持紫色火焰剑象征神圣意志的裁决。亚当凝视夏娃代表理性与感性的对话，生命树十二果实对应黄道十二宫，智慧树缠绕的蛇暗示知识带来的道德考验。背景火山喷发象征激情能量，远处雪山代表纯净初心。亚当足下的绿色大地与夏娃立足的红色岩石形成阴阳互补的视觉隐喻。\r\n\r\n原型\r\n灵魂伴侣、道德选择者、阴阳调和者、自由意志践行者、神圣契约见证人',1,'正位的恋人牌标志着人生重要转折点的到来，可能涉及情感承诺或价值观的重塑。在爱情中象征灵魂层面的深度连接，在事业中提示遵循内心声音的职业选择。这张牌强调选择背后的道德维度，提醒每个决定都塑造着自我认同。天使的祝福暗示超越世俗考量的精神契合，生命树与智慧树的并置则揭示知识与直觉的平衡之道。当面临重大抉择时，恋人牌要求我们聆听内在真实的渴望。','逆位的恋人牌反映内在价值体系的混乱，可能陷入情感与理智的撕裂状态。关系中存在未说破的隔阂，重大决策时被外界压力干扰。可能经历道德困境或信任危机，潜意识欲望与表面承诺产生矛盾。此时需要重新审视选择动机，修复自我认知的完整性。逆位也警示关系中的权力失衡或情感勒索，提醒建立健康的心理边界。'),
(7,'戰車 ',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/戰車 The Chariot.jpg','戰車牌描绘驾驭对立力量的王者形象，黑白天狮牵引的战车冲破城墙。象征意志力的胜利、对立能量的掌控以及灵肉合一的境界，体现通过自我控制达成目标的玄奥智慧。\r\n\r\n关键词\r\n意志胜利、自我控制、目标达成、对立调和、灵肉统一\r\n\r\n象征意义\r\n戰車八角华盖象征宇宙法则，车体立方结构代表物质世界的稳固。驾驭者胸甲刻有炼金术符号，头戴八芒星冠冕连接天界能量。黑白狮身人面兽象征阴阳力量的平衡驾驭，城墙缺口处的流水图案暗示突破限制的流动性。车轮上的翼狮纹章彰显精神对物质的超越，缰绳无物理连接展现纯粹意志力的操控艺术。\r\n\r\n原型\r\n意志驾驭者、矛盾统合者、灵性战士、目标导向者、能量指挥官',1,'\r\n正位的戰車象征着通过强大意志整合矛盾力量的能力。驾驭者需平衡理性与直觉、进取与克制，如同控制黑白狮子的缰绳。在事业中预示突破性进展，在竞争中展现战略优势。这张牌强调纪律性的重要，提醒保持明确方向感。当面临内在冲突时，战车能量教导将对立面转化为前进动力，通过灵性成长实现物质世界的成功。','逆位的戰車反映内在能量的失调，可能陷入犹豫不决或冲动冒进的两极。自我控制机制失效导致资源浪费，团队合作中出现权力斗争。此时需要重新校准目标优先级，修复意志力与行动力的连接。逆位也警示过度压抑情感可能引发心理问题，建议通过冥想或心理咨询恢复内在平衡。'),
(8,'力量',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/力量 Strength.jpg','力量牌展现柔韧克刚的智慧，女性徒手驯服雄狮的场景。象征内在力量的觉醒、原始本能的升华以及心灵对兽性的驯服，揭示以柔克刚的深层生命法则。\r\n\r\n关键词\r\n内在力量、以柔克刚、本能驾驭、勇气、耐心\r\n\r\n\r\n象征意义\r\n画面中女性头戴无限符号花环，象征与宇宙能量的永恒连接。右手轻抚狮颌展现非暴力驯服，左手维持平衡的姿势暗含阴阳调和。狮子尾巴夹于股间显示本能臣服，女性白衣的红色装饰带呼应原始生命力。背景的绿色山脉代表稳固的大地支持，空中飞舞的蝴蝶暗示灵魂的蜕变升华。\r\n\r\n原型\r\n心灵驯兽师、柔性能量大师、本能引导者、内在勇士、蜕变催化者',1,'正位的力量牌代表通过心灵而非蛮力达成目标的能力。她教导用同理心化解冲突，以持久耐心替代强硬对抗。在人际关系中展现包容的智慧，在危机处理时体现冷静的勇气。这张牌强调内在信念的重要性，提醒真正的力量源于自我掌控而非对外控制。当面对挑战时，力量牌指引我们连接内在神性，将原始欲望转化为创造性能量。','逆位的力量牌反映内在能量的失衡，可能表现为暴力倾向或过度压抑。自我怀疑削弱行动力，恐惧情绪导致决策失误。关系中可能出现权力斗争，健康方面需注意压力引发的免疫问题。此时需要重新建立与内在力量的连接，通过冥想或艺术表达疏导被压抑的情绪。逆位也警示勿将个人意志强加他人，学会尊重自然的发展节奏。'),
(9,'隐士',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/隐士 The Hermit.jpg','隐士牌描绘智者独行于雪山之巅，提灯照亮真理之路。象征内省求索、智慧沉淀与精神觉醒，体现通过孤独沉思获得超越性认知的生命阶段。\r\n\r\n关键词\r\n内省、智慧追寻、孤独成长、精神指引、真理启示\r\n\r\n象征意义\r\n隐士身披灰色斗篷立于雪峰，六芒星提灯中跃动着宇宙真理的火焰。右手木杖刻有蛇形螺旋，象征智慧攀升的路径。腰间系着代表物质世界的五角星，脚下冰晶形成神圣几何图案。背景银河倾泻如瀑，暗示个体意识与宇宙智慧的连接。斗篷褶皱形成的阴影构成卡巴拉生命之树的轮廓。\r\n\r\n原型\r\n真理追寻者、智慧守夜人、精神向导、孤独先知、宇宙意识载体',1,'正位的隐士牌代表必要的独处与精神探索时期。他提醒暂时远离世俗喧嚣，通过深度思考获得生命真谛。在学术研究中象征专注的洞察力，在人生转折期需要内在智慧的指引。这张牌强调内在光明的力量，教导我们真理往往在寂静中显现。当感到迷茫时，隐士能量建议退隐自省，等待内在答案的自然浮现。','逆位的隐士警示过度的自我封闭可能阻碍成长。表现为逃避社会责任或陷入虚无主义思考。可能因缺乏导师指引而迷失方向，或固执于错误认知。此时需要适度回归社群，平衡独处与交流。逆位也提醒勿将孤独浪漫化，真实的智慧需要与现实世界保持连接。'),
(10,'命运之轮',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/命运之轮 Wheel Of Fortune.jpg','命运之轮牌展现宇宙循环的永恒律动，中央轮盘刻满神秘符号由斯芬克斯守护。象征命运无常的流转、因果法则的运作以及灵魂进化的周期，揭示在变化中把握机遇的宇宙智慧。\r\n\r\n关键词\r\n命运转折、周期循环、机遇把握、因果业力、顺势而为\r\n\r\n象征意义\r\n轮盘中心刻有炼金术符号TARO，四角分别标注希伯来字母YHVH。轮缘流转的云蛇象征永恒运动，四福音兽守护宇宙四方。上升的安努比斯代表进化力量，下降的提丰象征衰退周期。轮轴八道光芒对应生命之树的八个源质，背景漩涡星云暗示宇宙创造与毁灭的永恒舞蹈。\r\n\r\n原型\r\n周期观测者、因果律行者、机遇捕手、业力清算者、宇宙舞者',1,'正位的命运之轮提示生命转折点的到来，可能迎来意想不到的机遇或挑战。强调顺应宇宙节律的重要性，在变化中保持觉知与灵活性。当旧周期结束新周期开启时，需清理业力包袱轻装前行。这张牌鼓励接纳生命潮汐的涨落，在命运转折处做出明智选择。同时提醒当下的选择将影响未来循环的轨迹，需以长远眼光看待眼前变化。','逆位的命运之轮警示可能陷入消极循环或重复性困境。抗拒必要改变导致发展停滞，过往业力显现需要直面解决。此时需打破惯性思维模式，主动创造改变而非被动等待。逆位也暗示需要重新评估人生方向，可能某些坚持已不符合当前生命周期的需求。通过释放对控制的执着，才能重新与宇宙律动同步。'),
(11,'正义',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/正义 Justice.jpg','正义牌呈现绝对平衡的宇宙法则，持剑执秤的女神端坐于双柱之间。象征因果律的精确运作、道德判断的清明以及灵魂契约的履行，揭示每个选择背后的业力回响。\r\n\r\n关键词\r\n因果报应、公平裁决、道德责任、法律事务、灵魂平衡  \r\n\r\n象征意义\r\n女神头戴方形冠冕象征物质界的秩序，右手垂直宝剑切断因果之线，左手天平精确测量灵魂重量。双柱后的紫色帷幕暗示隐藏的灵性维度，石座上的立方体雕刻代表显化法则。女神赤脚踏过蛇形图案，象征超越低阶欲望。天平两端分别盛放心脏与羽毛，对应古埃及的死后审判仪式。\r\n\r\n原型\r\n业力仲裁者、宇宙会计官、灵魂审判者、契约监督人、道德基准点',1,'正位的正义牌强调宇宙间精确的因果机制，每个行为都将产生对应的能量回响。在法律事务中预示公正裁决，在人际冲突中要求客观审视。这张牌提醒为自己的选择负全责，当前处境是过去决策的累积显现。当面临重大抉择时，正义女神的天秤提示需平衡理性与情感，利剑则象征斩断自欺的勇气。灵魂层面的平衡需要清理未完成的业力契约。','逆位的正义牌警示失衡的业力状态，可能遭遇不公待遇或陷入法律纠纷。逃避责任将导致更严重的后果，偏见影响判断的客观性。此时需要直面过往错误，通过修正行为恢复因果平衡。逆位也暗示某些隐藏的契约义务需要履行，提醒诚实面对自己与他人缔结的灵性协议。'),
(12,'倒吊者',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/倒吊者 The Hanged Man.jpg','倒吊者牌呈现智慧的反转视角，修行者倒悬于生命之树静观世界。象征牺牲奉献的觉悟、被动中的主动成长以及意识维度的提升，揭示停滞期的深层转化意义。\r\n\r\n关键词\r\n牺牲奉献、视角转换、被动成长、意识觉醒、等待时机\r\n\r\n象征意义\r\n倒吊者右足系着生命之树的活结，形成神圣几何三角构图。黄色光环环绕头部象征灵性觉醒，红色裤装代表尘世羁绊。双手背后的捆绑姿势暗喻自愿束缚，背景流动的水纹暗示意识之流的转变。左腿形成的数字4对应物质世界，整体构成炼金术符号象征灵性淬炼。\r\n\r\n原型\r\n觉悟者、被动智者、视角转换者、灵性牺牲者、意识炼金师',1,'正位的倒吊者象征主动选择的暂停期，通过换位思考获得更高智慧。在困境中保持超然态度，将限制转化为内省机会。财务上提示审慎投资，感情中需要换位理解。这张牌教导以退为进的哲学，提醒表面停滞实为内在质变的关键期。当遭遇瓶颈时，倒吊人能量建议暂时抽离，等待宇宙时机的成熟。','逆位的倒吊者警示无意义的自我折磨，可能陷入受害者情结或逃避责任。固执己见阻碍成长，强迫性重复消耗能量。此时需要打破思维定式，采取实际行动改变现状。逆位也暗示被动的处境已到极限，是时候结束等待状态，重新掌握人生主动权。'),
(13,'死神',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/死神 Death.jpg','死神牌揭示必然的终结与新生循环，黑袍骑士持旗策马穿越生死界限。象征旧有模式的彻底瓦解、深层意识的转化重生以及不可抗拒的宇宙法则，强调结束作为新生的必经之路。\r\n\r\n关键词\r\n终结转化、必然改变、深层蜕变、放下过去、新生序曲\r\n\r\n象征意义\r\n死神黑袍下的铠甲象征不朽灵魂，白马眼眸映出初升太阳预示新生。倒地的国王冠冕滚落代表世俗权力的终结，主教伸手祈求显示宗教慰藉的局限。河中漂浮的百合暗示灵魂的纯净不灭，背景双柱间的曙光象征穿越黑暗后的觉醒。旗帜上的黑玫瑰图案揭示死亡孕育的神秘智慧。\r\n\r\n原型\r\n周期终结者、灵魂炼金师、转化代理人、黑暗向导、重生接生婆',1,'正位的死神牌宣告不可逆转的转变时刻到来，旧有结构将经历根本性解体。这可能涉及关系结束、职业转型或价值体系的重构。虽然过程伴随痛苦，但牌面暗示这是灵魂进化的必要阶段。当坦然接受终结时，新的生命形式将从废墟中自然萌发。此时需要彻底释放不再服务成长的元素，信任宇宙的更新节奏。','逆位的死神牌反映对必要改变的抗拒，可能导致能量淤塞与精神僵化。可能沉溺于已逝的关系模式，或试图用表面改变掩盖深层问题。身体层面可能出现慢性疾病，财务方面需警惕惯性思维导致的损失。此时需要主动拥抱转变，通过仪式性告别帮助完成能量过渡。逆位也提醒注意假性重生的陷阱，确保改变触及核心层面。'),
(14,'节制',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/节制 Temperance.jpg','节制牌描绘天使调和生命之水的神秘仪式，双杯流转的金色液体象征对立元素的完美融合。代表灵性炼金术的转化过程、矛盾能量的动态平衡，以及通过适度原则达成的生命升华。\r\n\r\n关键词\r\n调和、平衡、转化、适度、灵性整合\r\n\r\n象征意义\r\n天使脚踏水面陆地交界处，象征物质与精神的桥梁作用。双翼颜色左蓝右红代表冷热能量的平衡，胸前方形符号暗示四次元的神圣几何。流动的金液中悬浮的炼金术符号Ξ代表未知元素，背景的虹光小径指向灵魂进化的方向。双杯底部的莲花与火焰纹饰分别象征纯净初心与转化激情。\r\n\r\n原型\r\n能量调酒师、矛盾调解者、灵性炼金术士、中庸守护者、进化引路人',1,'正位的节制牌象征生命能量的优化配置，教导在物质与精神间找到黄金分割点。在人际关系中促进不同立场的和解，在健康方面提示身心协调的重要性。这张牌强调渐进式改变的力量，提醒通过耐心调和实现质的飞跃。当面临对立选择时，节制牌指引寻找第三条道路，将看似矛盾的需求转化为协同增效的能量。','逆位的节制牌反映能量循环的阻滞，可能陷入非此即彼的思维困境。过度放纵或极端克制导致系统失衡，情感与理性产生严重脱节。此时需要重新校准生活节奏，通过断舍离恢复能量流动。逆位也警示强迫性重复模式，建议采用中庸之道打破恶性循环。'),
(15,'恶魔',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/恶魔 The Devil.jpg','恶魔牌揭示物质欲望的枷锁，羊头人身恶魔高踞欲望祭坛之上。象征无明导致的束缚、物质主义的沉溺以及灵魂的自我囚禁，警示被低阶欲望支配的生命状态。\r\n\r\n关键词\r\n欲望束缚、物质沉迷、权力操控、恐惧支配、灵性蒙蔽\r\n\r\n象征意义\r\n恶魔蝙蝠翅膀象征堕落灵性，倒立五芒星代表物质对精神的压制。男女囚徒头上的火焰暗示被扭曲的欲望，颈间锁链呈松弛状态揭示自我囚禁的本质。祭坛的黑色立方体象征物质主义牢笼，恶魔左手向下的火炬将神圣能量导向尘世欲望。背景的幽暗洞穴反映意识深处的阴影领域，石壁上隐约的锁链图案暗示集体潜意识的束缚。\r\n\r\n原型\r\n欲望支配者、物质牢笼建造者、阴影面化身、灵性堕落者、集体恐惧投影',1,'正位的恶魔牌揭示潜意识中的自我设限模式。可能表现为对金钱、权力或感官享受的过度依赖，关系中存在控制与依附的扭曲动态。这张牌提醒检查那些看似舒适实则窒息的生存状态，警示被恐惧驱动的非理性选择。在物质层面可能预示债务危机或成瘾问题，在灵性层面反映与高我连接的断裂。','逆位的恶魔牌象征打破精神桎梏的觉醒过程。可能经历重大生活变故促使重新评估价值观，开始戒除不良习惯或结束有毒关系。这个阶段需要直面内心恐惧，通过灵性实践恢复内在自由。逆位也提示潜在欲望的正向转化可能，将原始动能升华为创造性能量。'),
(16,'高塔',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/高塔 The Tower.jpg','高塔牌展现固有结构崩解的瞬间，闪电击毁高塔冠冕坠落。象征旧有认知的颠覆、虚假安全的破灭以及灵魂的强制觉醒，揭示通过剧变获得重生的宇宙法则。\r\n\r\n关键词\r\n突然剧变、认知颠覆、强制觉醒、虚假崩塌、重生前兆\r\n\r\n象征意义\r\n被击中的石塔象征人为构建的虚假安全体系，坠落的王冠代表世俗权力的瓦解。塔身裂缝中的火焰喷射象征压抑情绪的爆发，坠落的人体呈现惊讶与解脱的矛盾状态。背景的黑色暴雨云层暗示集体潜意识的动荡，海面波涛反映潜意识的剧烈波动。闪电的希伯来字母Yod形状象征神性介入，破碎的砖石显现金字塔结构暗示文明根基的动摇。\r\n\r\n原型\r\n结构破坏者、认知颠覆者、强制觉醒者、虚假安全爆破手、宇宙修正执行者',1,'正位的高塔牌预示不可抗拒的变革即将到来，可能涉及事业转折、关系破裂或信仰危机。闪电象征宇宙的修正力量，强制打破自欺的认知结构。虽然过程痛苦，但为必要的精神排毒。财务上警惕投资泡沫，健康注意突发性疾病。这个阶段需要放弃控制欲，学会在废墟中寻找新生契机。','逆位的高塔牌反映对变革的潜在抗拒，可能表现为粉饰太平或压抑危机。长期积累的问题面临临界点，延迟爆发可能造成更大破坏。此时需要主动进行结构改革，避免被动的灾难性崩溃。逆位也提示通过渐进方式实现转变的可能性，但需警惕虚假的安全感。'),
(17,'星星',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/星星 The Stars.jpg','星星牌展现希望重生的灵性图景，裸身少女将生命之水注入意识与潜意识之河。象征创伤后的疗愈、灵感的涌现以及宇宙能量的校准，传递超越黑暗的永恒希望。\r\n\r\n关键词\r\n希望重生、灵感涌现、心灵疗愈、宇宙连接、能量更新\r\n\r\n象征意义\r\n画面中央的八芒星象征宇宙意识的永恒指引，少女左右手各持金壶将生命之水注入意识之池与潜意识之河。背景的七颗小星对应七大脉轮，巨鸟栖息的树代表生命之树的复苏。脚下土地裂痕中萌发的新芽暗示创伤后的成长，远处山脉轮廓形成母性怀抱的守护形态。\r\n\r\n原型\r\n希望使者、宇宙通道、创伤疗愈者、灵感之源、能量校准师',1,'正位的星星牌象征创伤后的灵性复苏，如同黑夜后的第一缕晨光。提示通过艺术创作或志愿服务重新连接生命意义，在静心中接收宇宙指引。人际关系中带来谅解与宽恕的能量，健康方面预示自然疗愈力的启动。这张牌鼓励保持开放接收的状态，相信宇宙的完美时序安排。\r\n','逆位的星星牌反映希望之光的暂时遮蔽，可能经历信仰危机或灵感枯竭。此时需要检视是否过度依赖外在肯定，重新建立与内在神圣源的连接。可能表现为环保意识淡漠或人道主义精神衰退，提醒通过接触自然或艺术重燃生命热情。逆位也提示需要更落地的实践来支撑灵性理想。'),
(18,'月亮',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/月亮 The Moon.jpg','月亮牌展现潜意识海洋的潮汐波动，双犬对月长啸于蜿蜒小径两端。象征直觉的觉醒、深层恐惧的浮现以及现实与幻象的模糊边界，揭示心灵暗夜中的成长契机。\r\n\r\n关键词\r\n潜意識波動、直覺覺醒、恐懼幻象、情感迷惑、心靈暗夜\r\n\r\n象征意义\r\n月亮表面的忧郁人像象征潜意识的投影，双塔间的蜿蜒小径代表意识与无意识的交界。水中浮现的螯虾暗示原始恐惧的浮现，岸边的狼与狗象征被驯化与野性的心理力量。十三滴落珠对应月相周期，小径上的血滴标记心灵成长的阵痛。背景的深色水域反映集体无意识，远处山脉轮廓暗示有待探索的精神领域。\r\n\r\n原型\r\n潜意识导航者、直觉信使、阴影面向导、梦境解读者、心灵潮汐观测者',1,'正位的月亮牌反映潜意识领域的剧烈波动，可能经历莫名的焦虑或重复的梦境。直觉变得敏锐但信息模糊，需警惕自我欺骗与认知扭曲。在人际关系中暗示未说出口的猜疑，工作中可能遭遇隐藏的阻碍。这张牌提醒直面内心阴影，通过艺术表达或梦境解析整合被压抑的心理内容。\r\n','逆位的月亮牌象征意识之光的逐渐透入，开始看清恐惧的根源。直觉获得更清晰的指引，能够区分真实与虚幻。可能结束长期的情感困惑，或揭露被掩盖的事实。这个阶段适合进行心理疗愈，将潜意识素材转化为创造力。逆位也提示需要建立更稳定的现实根基来平衡敏感天性。'),
(19,'太阳',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/太阳 The Sun.jpg','太阳牌展现纯粹的生命喜悦，裸体孩童骑白马穿越金色原野。象征意识的光明、童真的智慧以及宇宙的丰盛馈赠，代表成功、活力与万物和谐共生的完美状态。\r\n\r\n关键词\r\n成功喜悦、活力充沛、真相明朗、健康成长、积极乐观\r\n\r\n象征意义\r\n画面中央孩童头戴向日葵冠冕，手持红色旗帜象征胜利的生命能量。白马无需缰绳控制体现天人合一的境界，围墙内的向日葵齐向太阳致敬。背景双柱突破云层直抵日轮，象征意识与无意识的完美融合。四朵向日葵对应四元素平衡，孩童背后的羽毛翅膀暗示精神升华。\r\n\r\n原型\r\n生命欢庆者、真理之光、纯真智者、宇宙宠儿、丰盛显化者',1,'正位的太阳牌预示充满光明与希望的发展阶段。在事业中象征公开透明的成功，学业反映高效的学习状态。人际关系充满真诚与温暖，健康方面显示强健的生命力。这张牌鼓励保持开放与信任，如同孩童般拥抱生命馈赠。提醒在顺境中保持谦逊，将个人成功转化为助人的能量。\r\n','逆位的太阳牌提示需注意能量过度耗散或盲目乐观。可能因成功冲昏头脑忽视潜在危机，或健康因过度消耗亮起红灯。关系中需避免强加自己的乐观给他人，学业事业警惕表面繁荣下的隐患。此时需要调整节奏，通过休息与自省恢复内在光芒。'),
(20,'审判',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/审判 Judgement.jpg','审判牌展现灵魂觉醒的最终召唤，天使加百列吹响末日号角唤醒棺中亡灵。象征因果法则的清算、旧我的彻底死亡以及灵性层面的重生，揭示业力循环终结时的终极转化。\r\n\r\n关键词\r\n灵魂觉醒、因果清算、重大转折、救赎召唤、业力释放\r\n\r\n象征意义\r\n画面中央天使加百列手持末日号角，金色光芒中浮现十字旗帜象征神圣救赎。从棺椁中升起的三人代表身心灵的重生，背景雪山暗示纯净意识的觉醒。海面漂浮的棺材盖板刻有埃及象形文字，暗喻古老智慧的复苏。号角飘出的七道声波对应七重天界，地面裂缝中涌出的水流象征潜意识能量的释放。\r\n\r\n原型\r\n因果仲裁者、灵魂唤醒者、业力终结者、重生引导者、宇宙法则执行者',1,'正位的审判牌标志着灵性层面的重大突破。可能经历生命阶段的彻底转换，旧有模式与关系的终结。天使的号角象征宇宙法则的召唤，提示对人生使命的觉醒。在事业中可能迎来职业转型，在关系中需要直面因果业力。这张牌强调接受生命赋予的第二次机会，通过忏悔与宽恕完成灵魂的净化。\r\n','逆位的审判牌反映对内在召唤的抗拒，可能因恐惧改变而停滞不前。未解决的业力导致重复相似困境，自我批判阻碍灵性成长。此时需要勇气面对过往错误，通过深度自省打破循环模式。逆位也警示逃避人生课题将导致更大危机，唯有直面因果才能获得真正自由。'),
(21,'世界',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/世界 The World.jpg','世界牌呈现完美循环的宇宙之舞，四活物环绕的裸体舞者手持双权杖。象征生命周期的完成、灵魂的圆满整合以及天人合一的至境，标志重大人生阶段的完美闭环。\r\n\r\n关键词\r\n圆满达成、周期完成、宇宙和谐、灵魂整合、全新开始\r\n\r\n象征意义\r\n舞者紫色绶带形成无限符号，象征永恒的生命循环。四角的人面狮身、鹰、牛、天使分别对应四元素与黄道四固定星座。环绕的桂冠暗示尘世成就，深蓝背景的星云图案代表宇宙子宫。舞者足尖触地的瞬间形成能量漩涡，右手权杖指引灵性进化，左手权杖连接物质根基。\r\n\r\n原型\r\n周期完成者、宇宙舞者、全一存在、新纪元开启者、无限循环化身',1,'正位的世界牌标志着重要人生阶段的完美收官。可能涉及学业完成、事业成就或灵性觉醒，象征所有努力结晶为完整成果。这张牌提示享受当下圆满，同时准备迎接新周期。四活物的方位暗示物质、情感、心智、灵性层面的全面整合，舞者的螺旋运动象征能量在闭合循环中的永恒流动。\r\n','逆位的世界牌反映收尾阶段的阻滞，可能因细节执着延误整体完成。需检查是否存在逃避完结的心理，或过度追求完美导致的行动瘫痪。这个阶段需要释放控制欲，接纳不完美中的完美。逆位也提示旧周期未完全结束前，新开始可能遭遇能量拉扯。'),
(22,'权杖一',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/权杖一','权杖一展现原始创造力的迸发，云端伸出的手紧握萌芽的权杖。象征新计划的启动、生命能量的觉醒以及灵感的瞬间绽放，预示充满可能性的崭新开端。\r\n\r\n关键词\r\n新契机、创造力爆发、事业启航、激情点燃、潜能觉醒\r\n\r\n象征意义\r\n从积云中伸出的右手紧握发芽的橡木权杖，新叶象征潜能的具象化。背景的城堡与河流代表物质世界的机遇，十二道阳光对应黄道十二宫的能量灌注。权杖底部的水晶球折射出彩虹光芒，暗示灵性启示与物质成就的结合。飘动的红丝带缠绕杖身，将原始能量引导为有序的创造流程。权杖王牌展现原始创造力的迸发，云端伸出的手紧握萌芽的权杖。象征新计划的启动、生命能量的觉醒以及灵感的瞬间绽放，预示充满可能性的崭新开端。\r\n\r\n',2,'正位的权杖一标志着充满活力的新起点。可能收到创业邀约、艺术灵感突现或重要的人生转折。这张牌鼓励抓住稍纵即逝的机会，将原始热情转化为具体行动。在关系中象征激情的重燃，在学业中提示创新思维的应用。提醒保持开放心态，像权杖新芽般吸收各种可能性。\r\n','逆位的权杖一反映创造性能量受阻的状态。可能遭遇项目延期、灵感枯竭或动力不足。此时需要检视是否存在自我设限的信念，或外界环境带来的制约。建议通过运动或接触大自然重新激活生命能量，调整计划节奏后再出发。逆位也提醒勿因急躁而仓促行动，需夯实基础再图发展。'),
(23,'权杖二',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/权杖二 Two Of Wands.jpg','权杖二展现立足当下谋划未来的智者形象，手持地球仪立于城垛眺望远方。象征潜在机遇的评估、长远视野的建立以及主动创造命运的决心，体现将愿景转化为行动的战略智慧。\r\n\r\n关键词\r\n未来规划、潜在机会、战略决策、主动掌控、视野扩展\r\n\r\n象征意义\r\n人物左手紧握固定于城垛的权杖象征现有根基，右手托举的地球仪代表探索欲望。远方河流暗示未知领域的丰饶可能，近处山坡盛开的花朵显示当下资源的充沛。腰间悬挂的钥匙与卷轴象征已掌握的知识体系，城旗飘扬方向与视线焦点形成张力，揭示理想与现实的辩证关系。天际线处的航船图案暗示即将展开的旅程。',2,'正位的权杖二象征战略布局的关键阶段。城堡代表已取得的成就，地球仪暗示待开发的领域。在事业中提示拓展新市场的良机，在学业中鼓励制定长期进修计划。这张牌强调动态平衡的重要性，需在稳定现状与冒险创新间找到支点。当面临多个选项时，权杖二能量建议采取主动姿态，通过风险评估选择最具成长性的路径。\r\n','逆位的权杖二反映决策机制的僵化，可能因过度分析导致错失良机。对未知领域的恐惧形成自我限制，现有成就成为继续前进的包袱。此时需要打破安全区的心理依赖，通过小规模试错重建行动信心。逆位也警示合作关系中可能出现的视野分歧，建议建立清晰的共同目标框架。'),
(24,'权杖三',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/权杖三 Three Of Wands.jpg','权杖三展现远见与期待的图景，商人立于山崖眺望海面帆影。象征计划进入实施阶段、跨领域合作的建立以及未来成果的预兆，体现战略布局与耐心等待的智慧。\r\n\r\n关键词\r\n战略规划、跨域合作、未来展望、耐心等待、机遇预兆\r\n\r\n象征意义\r\n画面中人物身着红袍象征行动热情，手持权杖与山崖两杖形成三角稳定结构。远方三艘帆船分别驶向不同方向，代表多元发展可能性。腰间望远镜突显远见卓识，脚下岩石纹路暗含地质时间尺度。海天交界处的金色曙光预示新机遇，左侧生长的绿植象征潜在生命力。',2,'正位的权杖三标志着计划从蓝图进入实践阶段。商业上预示跨国合作或市场拓展，个人发展建议进行长期规划。这张牌强调立足当前展望未来的格局观，提醒在等待成果时保持信心。海面三艘船象征不同发展路径的可能性，山崖位置提供全局视野。建议建立战略联盟，同时注意风险分散。\r\n','逆位的权杖三提示可能遭遇进展受阻或合作障碍。过度聚焦单一方向导致机会流失，国际事务中可能出现文化隔阂。此时需要重新评估计划可行性，加强沟通协调。逆位也警示盲目扩张的风险，建议采取更务实的阶段性目标。财务方面需注意海外投资的不确定性。'),
(25,'权杖四',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/权杖四 Four Of Wands.jpg','权杖四展现丰收庆典的欢腾场景，四根权杖撑起花环拱门，人群在城堡前舞蹈。象征阶段成就的庆祝、稳固基础的建立以及和谐社群的喜悦，体现物质与精神的双重丰盛。\r\n\r\n关键词\r\n庆典欢庆、家庭和谐、事业稳固、成果分享、社区联结\r\n\r\n象征意义\r\n四根权杖构成稳固方阵，顶端花环象征阶段成就的冠冕。城堡代表安全与传承，门前舞蹈人群展现社群活力。背景金色麦田预示物质丰收，蓝天白云象征清明心境。左侧溪流代表情感流动，右侧果树暗示持续成长。拱门上的葡萄纹样预示欢乐分享，飞鸟队形体现集体协作精神。',2,'正位的权杖四预示值得庆贺的人生阶段，可能涉及乔迁新居、事业里程碑或家庭喜事。在团队合作中象征稳固的伙伴关系，在个人成长中代表基础能力的夯实。这张牌鼓励分享成功喜悦，建议通过社交活动强化人际关系。城堡象征安全领域，花环拱门暗示通向新阶段的过渡仪式，整体能量提示享受当下丰盛的同时保持开放心态。\r\n','逆位的权杖四反映庆祝能量的阻滞，可能因突发事件推迟计划中的聚会。家庭或团队中出现潜在矛盾，合作关系缺乏稳固基础。此时需要重新检视目标设定是否合理，修复人际网络中的薄弱环节。逆位也提醒勿被表面成功迷惑，应深入评估成就的实质价值，避免在社交应酬中过度消耗精力。'),
(26,'权杖五',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/权杖五 Five Of Wands.jpg','权杖五展现动态冲突场景，五名青年在荒野中挥舞权杖激烈交锋。象征良性竞争、观点碰撞与能量释放，体现通过摩擦激发创造力的成长过程。\r\n\r\n关键词\r\n意见分歧、竞争冲突、能量碰撞、突破常规、成长阵痛\r\n\r\n象征意义\r\n画面中五支权杖交错构成动态十字，青年们服饰颜色对应五行能量。背景的枯树与新芽并存象征破坏与新生，地面裂痕暗示固有结构的打破。空中飞鸟呈冲突队形，云层漩涡状排列强化能量动荡感。右侧岩石上的蛇形纹路象征智慧在混乱中孕育，左上角隐约的太阳轮廓预示冲突后的明朗化。',2,'正位的权杖五预示充满活力的竞争阶段。在团队合作中可能经历观点碰撞，需注意将对抗能量转化为建设性讨论。学业或事业上出现多方角力，保持开放心态可收获新思路。感情中可能存在价值观摩擦，需建立良性沟通机制。这张牌提醒冲突是成长的催化剂，但需确保竞争不偏离核心目标。\r\n','逆位的权杖五警示能量错配的风险。可能陷入为争而争的消耗战，或逃避必要冲突导致问题累积。团队合作出现方向分歧，个人精力分散在多线任务。此时需要重新聚焦核心目标，建立清晰的冲突解决机制。逆位也提示可能通过第三方调解化解僵局，或转换视角发现共赢方案。'),
(27,'权杖六',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/权杖六 Six Of Wands.jpg','权杖六展现胜利归来的荣耀场景，骑士高举权杖接受群众欢呼。象征目标达成后的公众认可、个人成就的社会肯定以及领导力的有效展现，体现成功带来的精神激励。\r\n\r\n关键词\r\n公众认可、胜利凯旋、成就表彰、领导魅力、士气鼓舞\r\n\r\n象征意义\r\n画面中央骑士白马金鞍，手持胜利花环装饰的权杖。群众挥舞的六支小权杖形成能量拱门，象征集体意志的加持。背景城墙上飘扬的旗帜展示家族纹章，暗示传统与创新的结合。骑士披风红色内衬代表内在热情，白马象征纯净的胜利动机。地面散落的桂冠叶提醒荣誉的暂时性，远方朝阳预示新挑战的到来。',2,'正位的权杖六预示努力将获得应有的回报与认可。在事业中可能指项目成功收尾或晋升机会，在竞赛中象征优胜荣誉。这张牌强调集体成就中的个人贡献，提醒保持谦逊的同时享受应得的赞誉。当需要公众支持时，权杖六的能量有助于建立权威形象，但需注意成功后的责任承担。\r\n','逆位的权杖六警示虚荣心可能带来的危机。可能遭遇名不副实的质疑，或团队内部因嫉妒产生分裂。成功表象下隐藏管理漏洞，需重新评估真实成就价值。这个阶段应回归初心，用务实态度巩固成果，避免被掌声冲昏头脑。'),
(28,'权杖七',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/权杖七 Seven Of Wands.jpg','权杖七展现捍卫立场的坚定姿态，青年手持权杖在山坡上抵御六根来袭的权杖。象征信念的坚守、竞争中的坚持以及面对挑战的勇气，强调在压力下保持立场的必要性。\r\n\r\n关键词\r\n坚定立场、积极防御、竞争对抗、勇气考验、维护价值\r\n\r\n象征意义\r\n画面中青年占据制高点，六根权杖从下方不同角度袭来。他手持的权杖垂直立于中央，形成稳固的防御轴线。山坡象征奋斗的艰难历程，破损的鞋履暗示持久对抗的消耗。天空乌云密布但远方透出曙光，预示挑战中的希望。攻击权杖的混乱排列与防御权杖的笔直形成动与静的对比，展现危机中的定力。',2,'正位的权杖七提示需要为信念而战的时刻到来。可能面临多方竞争或不同意见的挑战，需展现领导力和决断力。这张牌鼓励坚守原则，即便处于劣势也要勇敢捍卫立场。在职场中可能预示职位竞争，在学业中象征坚持学习方向。提醒通过策略性思考将劣势转化为优势，保持灵活应对的同时不丢失核心价值。\r\n','逆位的权杖七反映防御姿态的崩溃，可能因压力过大选择妥协或逃避。团队中缺乏支持导致孤军奋战，决策时因顾虑过多而丧失主动权。此时需要重新评估战斗的必要性，区分值得坚持的原则与无谓的固执。逆位也提醒适时寻求盟友支持，避免因过度防御造成资源浪费。'),
(29,'权杖八',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/权杖八 Eight Of Wands.jpg','权杖八描绘八根权杖破空飞行的动态场景，象征急速进展、信息流通与能量释放。展现计划进入高速实施阶段，机遇如箭在弦需及时把握的态势。\r\n\r\n关键词\r\n快速进展、信息传递、旅行运、能量爆发、即时行动\r\n\r\n象征意义\r\n八根权杖呈抛物线轨迹飞越河流，象征能量突破地理限制。最前端权杖即将触地暗示行动进入收获阶段，后方权杖的间距渐增表现加速态势。背景晴空万里无云象征阻碍消除，河流反映情感能量的顺畅流动。右下角萌芽的新枝预示快速成长，飞鸟图案加强信息传递的意象。',2,'正位的权杖八预示事情将进入高速发展阶段，可能突然收到多个好消息或机遇。适合快速决策与行动，旅行或远程合作运势强劲。在沟通方面提示高效的信息交换，感情中可能迎来激情迸发期。这张牌强调把握时机的重要性，提醒当机立断避免错失良机。\r\n','逆位的权杖八反映能量流动受阻，可能出现技术故障或沟通误会。旅行计划可能延期，重要信息传递被延误。此时需检查计划中的漏洞，避免因急躁导致失误。逆位也警示过度扩张可能带来的混乱，建议建立优先级管理系统。'),
(30,'权杖九',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/权杖九 Nine Of Wands.jpg','权杖九描绘伤痕累累的守卫者持杖守望，八根立杖构成防御屏障。象征逆境中的坚持、经验积累的警惕以及危机管理的智慧，体现防御性进取的生存策略。\r\n\r\n关键词\r\n坚守阵地、经验防御、持久耐力、警惕未然、伤后恢复\r\n\r\n象征意义\r\n画面中守卫者头裹渗血绷带仍保持戒备姿态，九根权杖构成可攻可守的栅栏。背景八根权杖形成新月阵型，最后立杖作为防御支点。地面裂缝象征经历的战斗创伤，远方隐约移动的身影暗示潜在威胁。守卫者左脚微屈的姿势体现攻防转换的预备状态，磨损的护甲显示持久战的消耗痕迹。',2,'正位的权杖九代表基于经验的防御智慧。提示建立弹性防御机制，在保持警惕的同时预留恢复空间。可能预示危机尾声的坚守阶段，需要调动既有资源进行最后防御。在职场象征项目收尾的风险管控，在健康方面提醒慢性病的长期管理。强调从过往创伤中积累的生存智慧，在压力下保持战略定力。\r\n','逆位的权杖九警示防御机制失效的风险。可能因长期紧张导致判断力下降，过度防御反而制造新问题。关系中存在信任危机，工作中陷入重复性错误。此时需要调整防御策略，将被动抵抗转为主动解决。逆位也提醒关注身心耗竭信号，通过专业协助处理积累性创伤。'),
(31,'权杖十',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/权杖十 Ten Of Wands.jpg','权杖十描绘负重前行的艰辛，男子怀抱十根权杖迈向远方家园。象征过度承担的压力、目标驱动的疲惫以及责任与自由的失衡，警示超负荷状态对生命力的消耗。\r\n\r\n关键词\r\n超负荷、责任过重、精疲力尽、目标迷失、急需减负\r\n\r\n象征意义\r\n画面中男子弯腰背负十根权杖，视线被遮挡仍坚持前行。远方家园象征未竟的目标，黄昏天色暗示能量将尽。捆扎权杖的红色绳索代表被束缚的激情，磨损的衣物显示长期辛劳。脚下道路的碎石象征前行阻力，权杖末端触及地面暗示负担超出承受极限。背景的黄色田野与背负的黑暗形成对比，提示未被察觉的可用资源。',2,'正位的权杖十揭示过度承担导致的能量枯竭。可能因完美主义或害怕失败而包揽过多责任，陷入‘必须完成所有事’的思维陷阱。工作中预示项目积压，生活中反映家庭重担。这张牌提醒检查是否混淆了‘重要’与‘紧急’，警示持续高压可能引发健康危机。建议重新评估优先级，学习授权与拒绝的艺术。\r\n','逆位的权杖十象征从重压下解脱的过程。可能通过任务委派、调整预期或放弃非核心责任来恢复平衡。这个阶段需要培养自我关怀意识，建立健康的界限。逆位也提示危机后的复苏期，通过经验教训发展更可持续的工作模式。可能经历从‘拼命三郎’到‘智慧管理者’的转变。'),
(32,'权杖侍从',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/权杖侍从 Page Of Wands.jpg','权杖侍从展现初生牛犊的探索精神，少年手持萌芽权杖立于荒漠沙丘。象征新计划的启动、冒险精神的觉醒以及创造性灵感的迸发，体现火元素最纯粹的行动渴望。\r\n\r\n关键词\r\n新机探索、活力迸发、创意萌芽、冒险召唤、热情学习\r\n\r\n象征意义\r\n侍从身着橙黄相间服饰象征火元素能量，权杖顶端的新芽预示潜在生命力。脚下沙丘波纹体现行动轨迹，远方金字塔暗示待实现的目标。腰间水壶代表资源准备，蜥蜴快速爬过象征敏捷反应。天空烈日放射十二道光芒对应黄道十二宫，侍者赤足站立展现与大地能量的连接。背景旋风卷起沙尘暗示即将到来的变革力量。',2,'正位的权杖侍从预示充满活力的新阶段开启。可能收到旅行邀约或创意项目的邀请，需要以开放心态拥抱变化。在学习中展现强烈好奇心，在工作中体现主动进取精神。这张牌鼓励将灵感转化为具体行动，提醒保持初学者的热情与探索欲。可能代表需要培养新技能或开启副业，沙漠中的绿芽象征潜在成长可能。','逆位的权杖侍从反映能量分散导致的无效努力。可能因三分钟热度放弃计划，或同时开展过多项目导致精力耗散。此时需要聚焦核心目标，建立可持续的行动方案。逆位也警示勿被虚假机会迷惑，应通过系统学习夯实基础。可能表现为网络成瘾或浅尝辄止的学习模式，需培养持久专注力。'),
(33,'权杖骑士',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/权杖骑士 Knight Of Wands.jpg','权杖骑士展现如火般的行动能量，骑士策马驰骋于沙漠之中高举燃烧的权杖。象征冒险精神的迸发、目标的急速推进以及不受拘束的自由意志，体现火元素最纯粹的行动力。\r\n\r\n关键词\r\n迅猛行动、冒险精神、热情奔放、即兴发挥、开拓进取\r\n\r\n象征意义\r\n骑士红袍象征火元素的炽热能量，盔甲上的火蜥蜴纹章代表对火焰的掌控。战马跃起的姿态展现动态平衡，沙漠背景暗示行动需要克服的艰难环境。权杖顶端的三叉火焰象征创造、毁灭与转化的循环，马鬃如火焰般舞动强化运动感。远方的金字塔提示行动背后的长远目标，沙尘轨迹显示迅猛的行动速度。',2,'正位的权杖骑士象征充满激情的行动阶段。适合开展新项目、快速推进计划或进行冒险尝试。这张牌鼓励抓住机遇立即行动，以热情和勇气突破现状。在感情中可能预示热烈的追求，在事业中提示需要敏捷应对变化。提醒保持目标专注，将火元素的爆发力转化为持续动能。\r\n','逆位的权杖骑士警示能量失控的状态。可能因急躁导致错误决策，多个项目同时进行却难以完成。关系中存在不稳定因素，工作可能遭遇突发变故。此时需要调整节奏，培养耐心与持久力。逆位也提醒注意体能透支，避免因过度消耗影响长期发展。'),
(34,'权杖王后',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/权杖王后 Queen Of Wands.jpg','权杖王后端坐宝座手持向阳向日葵，脚边黑猫与狮子彰显王者气度。象征热情生命的绽放、目标明确的领导力以及直觉与行动力的完美结合，展现火元素阴性面的创造性能量。\r\n\r\n关键词\r\n活力四射、目标导向、自信领导、创造力、社交魅力\r\n\r\n象征意义\r\n王后宝座雕刻的狮子与向日葵象征太阳能量，手持权杖顶端的新芽预示持续成长。黑猫代表神秘直觉力，脚边石狮守护物质领域的成就。裙摆的火焰纹样暗示内在激情，背景金色麦田象征丰盛收获。宝座下的蝎子图案揭示隐藏的蜕变力量，向日葵追随太阳的特性比喻目标明确的行动轨迹。',2,'正位的权杖王后代表充满生命热情的领导者形象。她善于激发团队潜能，在事业中展现果断决策力，在社交场合散发天然魅力。这张牌提示把握创业良机，鼓励用热情感染他人。在感情中象征充满激情的伴侣，在创作中预示灵感的迸发。提醒保持目标专注，同时为他人保留成长空间。','逆位的权杖王后反映火元素能量的失衡，可能表现为控制欲过强或精力分散。工作中易与同事发生权力冲突，决策时因过度自信导致失误。情感关系中存在占有欲问题，创作陷入重复套路。此时需要调整领导方式，通过冥想恢复内在平衡，学习将个人能量转化为集体动力。'),
(35,'权杖国王',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/权杖国王 King Of Wands.jpg','权杖国王展现火焰元素的终极掌控，王者手持开花权杖稳坐狮纹王座。象征创造力的巅峰、创业精神的典范以及领导力的完美体现，代表将激情转化为持久成就的智慧。\r\n\r\n关键词\r\n领袖魅力、创业魄力、远见卓识、激情管理、成就导向\r\n\r\n象征意义\r\n王座两侧的狮首象征被驯服的原始力量，权杖顶端的新芽预示持续成长。国王披风内衬的火蜥蜴纹样代表对火焰元素的绝对掌控，足边的沙漠植物展现逆境生存智慧。背景的火山与绿洲并置暗示危险与机遇共存，王冠上的琥珀宝石凝聚千年能量，右手姿态既坚定又开放，体现权威与包容的平衡。',2,'正位的权杖国王代表成熟的企业家精神与战略眼光。他善于将创意转化为实际成果，在团队中激发热情并保持明确方向。这张牌提示需要展现权威与远见的时刻，鼓励大胆行动同时保持自律。在事业中预示扩张机遇，在项目中需要坚定领导。提醒真正的领袖力量源于清晰的愿景与对团队潜能的信任。','逆位的权杖国王警示领导力的失衡状态。可能表现为刚愎自用或过度冒险，决策时忽视现实条件。团队中因缺乏耐心导致人才流失，项目因准备不足面临失败风险。此时需要重新评估目标可行性，培养倾听能力，将个人激情与集体智慧相结合。逆位也提醒注意工作与生活的平衡，避免精力透支。'),
(36,'圣杯一',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/圣杯一','圣杯一象征着情感的开始和心灵的开放。它代表着新的情感体验和精神上的觉醒，通常与爱情、同情和直觉的提升有关。\r\n\r\n关键词\r\n情感的开始、心灵的开放、爱、同情、直觉\r\n\r\n象征意义\r\n圣杯一通常描绘一只手从云中伸出，握着一个溢满水的杯子，象征着情感的丰盈和心灵的开放。水流溢出杯子，象征着情感的流动和精神的滋养。莲花漂浮在水面上，象征着纯洁和精神的觉醒。',3,'正位的圣杯一象征着情感的开始和心灵的开放。它代表着新的情感体验和精神上的觉醒，通常与爱情、同情和直觉的提升有关。这个牌位可能预示着一段新的浪漫关系的开始，或者是现有关系的深化。它也可能表示一种新的精神觉醒，带来内心的平和与满足。\r\n','逆位的圣杯一可能表示情感的封闭和心灵的阻塞。它可能预示着情感上的失落或孤独感，或者是与他人之间的误解和隔阂。这个牌位可能提醒你需要重新审视自己的情感状态，寻找内心的平和与和谐。'),
(37,'圣杯二',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/圣杯二 Two Of Cups.jpg','圣杯二象征着情感的共鸣与关系的平衡。它代表着深刻的精神连接，强调合作与理解的重要性。通常预示着新关系的开始或现有关系的深化，带来情感上的满足和心灵的滋养。提醒我们在关系中保持开放和诚实，以促进彼此的成长和幸福。\r\n\r\n关键词\r\n情感共鸣、关系平衡、合作、理解、精神连接\r\n\r\n象征意义\r\n圣杯二通常描绘一对男女互相举杯，象征着情感的共鸣和关系的平衡。杯子中的水代表着情感的流动和精神的滋养，体现了和谐的能量交换和彼此的尊重。背景中的水流和莲花象征着纯洁和精神的觉醒，强调了合作与理解的重要性。这张牌提醒我们在关系中保持开放和诚实，以促进彼此的成长和幸福。',3,'正位的圣杯二象征着情感的和谐与关系的平衡。它代表着一种深刻的精神连接，强调了合作与理解的重要性。这张牌通常预示着一段新的关系的开始，或者是现有关系的深化，带来情感上的满足和心灵的滋养。它提醒我们在关系中保持开放和诚实，以促进彼此的成长和幸福。\r\n','逆位的圣杯二可能表示情感的失衡和关系中的紧张。它可能预示着权力斗争、误解或情感上的隔阂。这张牌提醒我们需要重新审视关系中的动态，努力恢复平衡和和谐。它可能暗示需要更多的沟通和理解，以克服障碍并重建信任和连接。'),
(38,'圣杯三',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/圣杯三 Three Of Cups.jpg','圣杯三象征着庆祝、友谊和团结。它代表着与朋友和家人共享快乐时光，强调社交和情感支持的重要性。这张牌通常预示着聚会、婚礼或其他庆祝活动，提醒我们珍惜与他人的联系。\r\n\r\n关键词\r\n庆祝、友谊、团结、社交、支持\r\n\r\n象征意义\r\n圣杯三通常描绘三个人举杯庆祝，象征着友谊和团结。杯子中的水代表着情感的流动和分享，体现了社交的快乐和支持。背景中的花朵和阳光象征着生命的美好和希望，强调了庆祝和感恩的重要性。这张牌提醒我们珍惜与他人的联系，享受生活中的美好时刻。',3,'正位的圣杯三象征着庆祝和团结。它代表着与朋友和家人共享快乐时光，强调社交和情感支持的重要性。这张牌通常预示着聚会、婚礼或其他庆祝活动，提醒我们珍惜与他人的联系，享受生活中的美好时刻。\r\n','逆位的圣杯三可能表示孤立和误解。它可能预示着社交疲惫或情感上的疏远，提醒我们需要重新审视与他人的关系，努力恢复联系和理解。'),
(39,'圣杯四',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/圣杯四 Four Of Cups.jpg','圣杯四描绘静坐冥想的青年对眼前三个圣杯无动于衷，云端递来的第四个圣杯亦被忽视。象征情感倦怠、机会错失以及内在反思的必要，提醒关注被忽略的心灵需求。\r\n\r\n关键词\r\n情感麻木、机会忽视、自我封闭、内在空虚、需要自省\r\n\r\n象征意义\r\n圣杯四通常描绘一个青年坐在树下冥想，面前的三个圣杯被忽视，第四个圣杯从云中递来却未被注意。象征着情感的麻木和对机会的忽视，提醒我们需要进行内省，关注被忽略的心灵需求。背景中的树和云象征着内在的反思和精神的觉醒，强调了保持开放心态的重要性。',3,'正位的圣杯四象征着情感的麻木和机会的忽视。它代表着一种内在的空虚和自我封闭，提醒我们需要进行内省，关注被忽略的心灵需求。这张牌通常预示着对现状的不满和对新机会的漠视，提醒我们要保持开放的心态，接纳新的可能性。\r\n','逆位的圣杯四可能表示重新投入和情感的复苏。它可能预示着打破冷漠和接纳新机会的时机，提醒我们要提升觉知，重新连接内心的需求和外界的机会。'),
(40,'圣杯五',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/圣杯五 Five Of Cups.jpg','圣杯五描绘一个人站在倒下的三个圣杯前，象征着失落和悔恨。它提醒我们关注失去的同时，也要看到仍然存在的机会和希望，强调从失望中恢复的重要性。\r\n\r\n关键词\r\n失落、悔恨、悲伤、专注于失去、忽视机会\r\n\r\n象征意义\r\n圣杯五通常描绘一个人站在倒下的三个圣杯前，背后还有两个完好的圣杯，象征着失落和悔恨。倒下的杯子代表着失去和悲伤，而完好的杯子则象征着仍然存在的机会和希望。背景中的河流和桥梁象征着情感的流动和跨越障碍的可能性，提醒我们要从失望中恢复，看到生活中的美好。',3,'正位的圣杯五象征着失落和悔恨。它代表着对过去的悲伤和对失去的专注，提醒我们需要从失望中恢复，看到仍然存在的机会和希望。这张牌通常预示着情感上的挑战，提醒我们要接受现实，继续前进。\r\n','逆位的圣杯五可能表示恢复和希望。它可能预示着从失望中走出，重新发现生活中的美好，提醒我们要接受过去，迎接新的开始。'),
(41,'圣杯六',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/圣杯六 Six Of Cups.jpg','圣杯六象征着怀旧和童年的回忆。它代表着过去的快乐时光和纯真的情感，提醒我们珍惜简单的快乐和无忧无虑的时光。这张牌通常预示着与过去的联系和对旧友的怀念。\r\n\r\n关键词\r\n怀旧、童年、纯真、简单的快乐、旧友\r\n\r\n象征意义\r\n圣杯六通常描绘两个孩子在花园中互赠杯子，象征着童年的纯真和简单的快乐。杯子中的花朵代表着成长和美好，背景中的房屋象征着安全和家庭的温暖。这张牌提醒我们珍惜简单的快乐和无忧无虑的时光，从过去中汲取力量，迎接未来。',3,'正位的圣杯六象征着怀旧和童年的回忆。它代表着过去的快乐时光和纯真的情感，提醒我们珍惜简单的快乐和无忧无虑的时光。这张牌通常预示着与过去的联系和对旧友的怀念，提醒我们要从过去中汲取力量，迎接未来。\r\n','逆位的圣杯六可能表示逃避现实和过度怀旧。它可能预示着停滞不前和拒绝成长，提醒我们要从过去中走出，接受变化和成长的机会。'),
(42,'圣杯七',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/圣杯七 Seven Of Cups.jpg','圣杯七象征着幻想和选择的多样性。它代表着各种可能性和诱惑，提醒我们在做决定时要保持清醒和理智。这张牌通常预示着面临选择的时刻，提醒我们要仔细权衡利弊。\r\n\r\n关键词\r\n幻想、选择、可能性、诱惑、决策\r\n\r\n象征意义\r\n圣杯七通常描绘七个杯子悬浮在云中，每个杯子中都有不同的象征物，象征着幻想和选择的多样性。云代表着幻想和不确定性，杯子中的物品象征着不同的可能性和诱惑。这张牌提醒我们在做决定时要保持清醒和理智，避免被幻想所迷惑。',3,'正位的圣杯七象征着幻想和选择的多样性。它代表着各种可能性和诱惑，提醒我们在做决定时要保持清醒和理智。这张牌通常预示着面临选择的时刻，提醒我们要仔细权衡利弊，避免被幻想所迷惑。\r\n','逆位的圣杯七可能表示清晰和现实。它可能预示着从幻想中走出，重新专注于现实和实际的选择，提醒我们要面对现实，做出明智的决定。'),
(43,'圣杯八',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/圣杯八 Eight Of Cups.jpg','圣杯八象征着放弃和追求更高的目标。它代表着离开不再满足的事物，追求更深层次的意义和满足感。这张牌通常预示着转变和自我发现的旅程，提醒我们要勇敢地追求内心的渴望。\r\n\r\n关键词\r\n放弃、追求、转变、自我发现、内心渴望\r\n\r\n象征意义\r\n圣杯八通常描绘一个人离开八个杯子，走向远方的山丘，象征着放弃和追求更高的目标。杯子代表着过去的成就和满足感，而远方的山丘象征着新的挑战和更高的目标。这张牌提醒我们要勇敢地追求内心的渴望，迎接新的挑战和成长的机会。',3,'正位的圣杯八象征着放弃和追求更高的目标。它代表着离开不再满足的事物，追求更深层次的意义和满足感。这张牌通常预示着转变和自我发现的旅程，提醒我们要勇敢地追求内心的渴望，迎接新的挑战。\r\n','逆位的圣杯八可能表示逃避和恐惧改变。它可能预示着停滞和拒绝成长，提醒我们要面对内心的冲突，勇敢地迎接变化和成长的机会。'),
(44,'圣杯九',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/圣杯九 Nine Of Cups.jpg','圣杯九象征着满足和愿望的实现。它代表着情感上的满足和成就，提醒我们珍惜已经拥有的幸福和成就。这张牌通常预示着愿望的实现和内心的满足，提醒我们要感恩和享受生活中的美好。\r\n\r\n关键词\r\n满足、愿望实现、成就、幸福、感恩\r\n\r\n象征意义\r\n圣杯九通常描绘一个人坐在九个杯子前，面带微笑，象征着满足和愿望的实现。杯子代表着情感上的成就和满足感，背景中的丰盛象征着幸福和成功。这张牌提醒我们要感恩和享受生活中的美好，珍惜已经拥有的幸福和成就。',3,'正位的圣杯九象征着满足和愿望的实现。它代表着情感上的满足和成就，提醒我们珍惜已经拥有的幸福和成就。这张牌通常预示着愿望的实现和内心的满足，提醒我们要感恩和享受生活中的美好，珍惜当下的幸福。\r\n','逆位的圣杯九可能表示不满和过度自满。它可能预示着空虚和失望，提醒我们要避免贪婪和过度追求物质，关注内心的真正需求。'),
(45,'圣杯十',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/圣杯十 Ten Of Cups.jpg','圣杯十象征着家庭的幸福和情感的圆满。它代表着和谐的家庭生活和持久的幸福，提醒我们珍惜与家人和爱人之间的联系。这张牌通常预示着情感上的圆满和家庭的和谐，提醒我们要感恩和享受生活中的美好。\r\n\r\n关键词\r\n家庭幸福、情感圆满、和谐、持久幸福、感恩\r\n\r\n象征意义\r\n圣杯十通常描绘一个家庭在彩虹下欢庆，象征着家庭的幸福和情感的圆满。彩虹代表着希望和和谐，杯子象征着情感的成就和满足感。这张牌提醒我们要感恩和享受生活中的美好，珍惜与家人和爱人之间的联系。',3,'正位的圣杯十象征着家庭的幸福和情感的圆满。它代表着和谐的家庭生活和持久的幸福，提醒我们珍惜与家人和爱人之间的联系。这张牌通常预示着情感上的圆满和家庭的和谐，提醒我们要感恩和享受生活中的美好，珍惜当下的幸福。\r\n','逆位的圣杯十可能表示家庭不和和情感的失落。它可能预示着短暂的幸福和失去联系，提醒我们要面对冲突，努力恢复和谐和联系。'),
(46,'圣杯侍从',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/圣杯侍从 Page Of Cups.jpg','圣杯侍从象征着新的情感体验和创意的萌芽。它代表着开放的心态和接受新事物的愿望，提醒我们要保持好奇心和接受变化。这张牌通常预示着新的情感体验和创意的到来，提醒我们要保持开放和接受的态度。\r\n\r\n关键词\r\n新体验、创意、好奇心、开放、接受\r\n\r\n象征意义\r\n圣杯侍从通常描绘一个年轻人手持圣杯，杯中有一条鱼，象征着新的情感体验和创意的萌芽。鱼代表着潜在的创意和情感的流动，年轻人象征着开放的心态和接受新事物的愿望。这张牌提醒我们要保持好奇心和接受变化，迎接新的机会。',3,'正位的圣杯侍者象征着新的情感体验和创意的萌芽。它代表着开放的心态和接受新事物的愿望，提醒我们要保持好奇心和接受变化。这张牌通常预示着新的情感体验和创意的到来，提醒我们要保持开放和接受的态度，迎接新的机会。\r\n','逆位的圣杯侍从可能表示幼稚和情感不成熟。它可能预示着创意受阻和封闭的心态，提醒我们要克服内心的障碍，开放心态，接受新的体验和变化。'),
(47,'圣杯骑士',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/圣杯骑士 Knight Of Cups.jpg','圣杯骑士象征着浪漫和追求梦想的勇气。它代表着情感的表达和追求理想的决心，提醒我们要勇敢地追求内心的渴望。这张牌通常预示着浪漫的到来和情感的表达，提醒我们要勇敢地追求梦想。\r\n\r\n关键词\r\n浪漫、追求梦想、情感表达、勇气、理想\r\n\r\n象征意义\r\n圣杯骑士通常描绘一个骑士手持圣杯，骑马前行，象征着浪漫和追求梦想的勇气。圣杯代表着情感的表达和理想的追求，骑士象征着勇气和决心。这张牌提醒我们要勇敢地追求内心的渴望，迎接新的情感体验和理想的实现。',3,'正位的圣杯骑士象征着浪漫和追求梦想的勇气。它代表着情感的表达和追求理想的决心，提醒我们要勇敢地追求内心的渴望。这张牌通常预示着浪漫的到来和情感的表达，提醒我们要勇敢地追求梦想，迎接新的情感体验。\r\n','逆位的圣杯骑士可能表示幻想和情感不稳定。它可能预示着逃避现实和犹豫不决，提醒我们要面对现实，找到方向，勇敢地追求理想。'),
(48,'圣杯王后',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/圣杯王后 Queen Of Cups.jpg','圣杯王后象征着情感的深度和直觉的力量。她代表着同情心和理解力，提醒我们要倾听内心的声音，关注他人的情感需求。这张牌通常预示着情感的成熟和直觉的增强，提醒我们要信任自己的直觉，关心他人。\r\n\r\n关键词\r\n情感深度、直觉、同情心、理解力、关心\r\n\r\n象征意义\r\n圣杯王后通常描绘一位坐在宝座上的女性，手持圣杯，象征着情感的深度和直觉的力量。圣杯代表着情感的流动和直觉的力量，皇后象征着同情心和理解力。这张牌提醒我们要倾听内心的声音，关注他人的情感需求，提供支持和理解。',3,'正位的圣杯王后象征着情感的深度和直觉的力量。她代表着同情心和理解力，提醒我们要倾听内心的声音，关注他人的情感需求。这张牌通常预示着情感的成熟和直觉的增强，提醒我们要信任自己的直觉，关心他人，提供支持和理解。\r\n','逆位的圣杯王后可能表示情感不稳定和过度敏感。它可能预示着依赖和情感封闭，提醒我们要面对情感的挑战，开放心态，避免误解和情感的封闭。'),
(49,'圣杯国王',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/圣杯国王 King Of Cups.jpg','圣杯国王象征着情感的平衡和智慧的领导。它代表着情感的成熟和理智的决策，提醒我们要在情感和理智之间找到平衡。这张牌通常预示着情感的稳定和智慧的指导，提醒我们要信任自己的判断，提供情感上的支持和指导。\r\n\r\n关键词\r\n情感平衡、智慧、领导、成熟、支持\r\n\r\n象征意义\r\n圣杯国王通常描绘一位坐在宝座上的国王，手持圣杯，象征着情感的平衡和智慧的领导。圣杯代表着情感的流动和智慧的力量，国王象征着成熟和理智的决策。这张牌提醒我们要在情感和理智之间找到平衡，提供情感上的支持和指导。',3,'正位的圣杯国王象征着情感的平衡和智慧的领导。它代表着情感的成熟和理智的决策，提醒我们要在情感和理智之间找到平衡。这张牌通常预示着情感的稳定和智慧的指导，提醒我们要信任自己的判断，提供情感上的支持和指导，成为他人的情感支柱。\r\n','逆位的圣杯国王可能表示情感压抑和操控。它可能预示着情感的不稳定和冷漠，提醒我们要面对情感的挑战，避免操控和误导，保持情感的平衡和理智。'),
(50,'宝剑一',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/宝剑一 Ace Of Swords.jpg','宝剑一代表着清晰的思维和真理的揭示。它象征着一个新的开始，充满了智慧和洞察力。这个牌面通常预示着一个重要的决定或突破性的想法的出现，帮助你克服障碍并取得成功。无论是在个人生活还是职业生涯中，这张牌都提醒你要保持头脑清醒，勇敢面对挑战，迎接新的机遇。\r\n\r\n关键词\r\n清晰、真理、洞察力、新的开始\r\n\r\n象征意义\r\n宝剑王牌通常描绘一把直立的剑，剑尖指向天空，象征着真理和正义。剑的两侧可能有云朵，象征着思维的清晰和洞察力的提升。这个牌面也可能包含其他象征元素，如皇冠或光芒，进一步强调其权威和启示的性质。剑的象征意义在于它的双刃，代表着真理的两面性和决策的复杂性。持剑者需要小心谨慎，以确保他们的行动符合道德和正义。',4,'正位的宝剑一象征着一个充满智慧和洞察力的开始。它可能预示着一个重要的决定或突破性的想法的出现，帮助你克服障碍并取得成功。这个牌面也可能表示真理的揭示和清晰的思维。无论是在个人生活还是职业生涯中，这张牌都提醒你要保持头脑清醒，勇敢面对挑战，迎接新的机遇。\r\n','逆位的宝剑一可能表示混乱和误解。它可能预示着延迟和挫折，或者是由于缺乏清晰的思维而导致的错误决策。这个牌面提醒你在做决定时要小心谨慎，避免仓促行事。逆位的宝剑王牌也可能暗示着需要重新评估当前的状况，以便找到更好的解决方案。'),
(51,'宝剑二',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/宝剑二 Two Of Swords.jpg','宝剑二代表着决策的困境和内心的冲突。这个牌面通常描绘一个蒙着眼睛的人，手持交叉的剑，象征着不愿面对的选择和内心的矛盾。它提醒我们在做出决定时要平衡理性和情感，避免被情绪左右。\r\n\r\n关键词\r\n决策、平衡、内心冲突、犹豫\r\n\r\n象征意义\r\n宝剑二通常描绘一个蒙着眼睛的人，手持交叉的剑，坐在一个平静的水面前。这个形象象征着决策的困境和内心的冲突。蒙着的眼睛代表着不愿面对的选择，而交叉的剑则象征着内心的矛盾和犹豫不决。水面象征着情感的深度和潜在的平静，提醒我们在做出决定时要平衡理性和情感。',4,'正位的宝剑二象征着在决策过程中面临的困境和内心的冲突。它可能表示你需要在两个选择之间做出决定，而这两个选择都具有重要意义。这个牌面提醒你要在理性和情感之间找到平衡，避免被情绪左右。通过冷静分析和深思熟虑，你将能够做出明智的决定。\r\n','逆位的宝剑二可能表示混乱和逃避。你可能在面对重要决定时感到不知所措，或者因为害怕做出错误的选择而选择逃避。这个牌面提醒你要正视问题，勇敢面对挑战，避免优柔寡断。通过积极的沟通和自我反省，你将能够找到解决问题的方法。'),
(52,'宝剑三',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/宝剑三 Three Of Swords.jpg','宝剑三代表着心灵的痛苦和情感的创伤。这个牌面通常描绘一颗被三把剑刺穿的心，象征着失落、悲伤和分离。它提醒我们在面对痛苦时要勇敢，接受情感的治愈过程，并从中学习和成长。\r\n\r\n关键词\r\n心痛、悲伤、分离、失落\r\n\r\n象征意义\r\n宝剑三通常描绘一颗被三把剑刺穿的心，背景是阴云密布的天空。这个形象象征着心灵的痛苦和情感的创伤。被刺穿的心代表着失落和悲伤，而阴云则象征着情感的动荡和不安。这个牌面提醒我们在面对痛苦时要勇敢，接受情感的治愈过程，并从中学习和成长。',4,'正位的宝剑三象征着心灵的痛苦和情感的创伤。它可能表示失去亲人、分手或其他形式的情感痛苦。这个牌面提醒我们要勇敢面对痛苦，接受情感的治愈过程，并从中学习和成长。通过理解和宽恕，我们可以从痛苦中解脱出来，迎接新的开始。\r\n','逆位的宝剑三可能表示愈合和恢复。你可能正在从过去的痛苦中走出来，开始宽恕自己和他人。这个牌面提醒我们要接受情感的治愈过程，放下过去的伤痛，迎接新的开始。通过积极的态度和自我反省，我们可以从痛苦中解脱出来，迎接新的生活。'),
(53,'宝剑四',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/宝剑四 Four Of Swords.jpg','宝剑四代表着休息和恢复的必要性。这个牌面通常描绘一个躺在墓地中的骑士，象征着在经历了挑战和冲突之后的休息和反思。它提醒我们在继续前进之前要花时间恢复精力，重新评估我们的目标和计划。\r\n\r\n关键词\r\n休息、恢复、反思、静养\r\n\r\n象征意义\r\n宝剑四通常描绘一个躺在墓地中的骑士，背景是彩色玻璃窗。这个形象象征着休息和恢复的必要性。躺着的骑士代表着在经历了挑战和冲突之后的休息和反思，而彩色玻璃窗则象征着精神的启示和内心的平静。这个牌面提醒我们在继续前进之前要花时间恢复精力，重新评估我们的目标和计划。',4,'正位的宝剑四象征着休息和恢复的必要性。它可能表示在经历了挑战和冲突之后，你需要花时间恢复精力，重新评估你的目标和计划。这个牌面提醒我们在继续前进之前要花时间反思和恢复，以便更好地应对未来的挑战。\r\n','逆位的宝剑四可能表示不安和焦虑。你可能感到过度劳累，无法找到时间休息和恢复。这个牌面提醒我们要注意自己的健康和幸福，避免过度劳累和压力。通过积极的休息和自我反省，我们可以更好地应对未来的挑战。'),
(54,'宝剑五',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/宝剑五 Five Of Swords.jpg','宝剑五代表着冲突和不和。这个牌面通常描绘一个胜利者手持剑，背景中有失败者离去，象征着胜利的代价和人际关系的紧张。它提醒我们在追求胜利时要考虑到他人的感受，避免不必要的冲突和争执。\r\n\r\n关键词\r\n冲突、胜利的代价、不和、争执\r\n\r\n象征意义\r\n宝剑五通常描绘一个胜利者手持剑，背景中有失败者离去。这个形象象征着胜利的代价和人际关系的紧张。胜利者的姿态显示出自信和骄傲，而失败者的离去则象征着失落和不和。这个牌面提醒我们在追求胜利时要考虑到他人的感受，避免不必要的冲突和争执。',4,'正位的宝剑五象征着冲突和不和。它可能表示在追求胜利的过程中，你可能忽视了他人的感受，导致人际关系的紧张。这个牌面提醒我们在追求目标时要考虑到他人的感受，避免不必要的冲突和争执。通过理解和谅解，我们可以改善人际关系，创造和谐的环境。\r\n','逆位的宝剑五可能表示和解和谅解。你可能正在努力修复过去的冲突，寻求与他人的合作。这个牌面提醒我们要放下过去的争执，努力创造和谐的环境。通过积极的沟通和合作，我们可以改善人际关系，实现共同的目标。'),
(55,'宝剑六',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/宝剑六 Six Of Swords.jpg','宝剑六代表着过渡和前进。这个牌面通常描绘一个小船载着几个人，驶向更平静的水域，象征着从困境中解脱出来，走向更好的未来。它提醒我们在面对困难时要保持希望，勇敢地迎接变化和新的开始。\r\n\r\n关键词\r\n过渡、前进、解脱、变化\r\n\r\n象征意义\r\n宝剑六通常描绘一个小船载着几个人，驶向更平静的水域。这个形象象征着过渡和前进。小船代表着从困境中解脱出来，驶向更好的未来，而平静的水域则象征着希望和新的开始。这个牌面提醒我们在面对困难时要保持希望，勇敢地迎接变化和新的开始。',4,'正位的宝剑六象征着过渡和前进。它可能表示你正在从困境中解脱出来，走向更好的未来。这个牌面提醒我们在面对困难时要保持希望，勇敢地迎接变化和新的开始。通过积极的态度和勇敢的行动，我们可以克服困难，实现目标。\r\n','逆位的宝剑六可能表示停滞和困境。你可能感到被困在某个困境中，无法前进。这个牌面提醒我们要正视问题，勇敢面对挑战，避免逃避和拖延。通过积极的态度和勇敢的行动，我们可以克服困难，实现目标。'),
(56,'宝剑七',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/宝剑七 Seven Of Swords.jpg','宝剑七代表着策略和隐秘行动。这个牌面通常描绘一个人偷偷地带走几把剑，象征着秘密和策略。它提醒我们在处理复杂问题时要小心谨慎，避免不诚实的行为，并考虑到行动的后果。\r\n\r\n关键词\r\n策略、隐秘、谨慎、计划\r\n\r\n象征意义\r\n宝剑七通常描绘一个人偷偷地带走几把剑，背景是一个营地。这个形象象征着策略和隐秘行动。偷偷带走的剑代表着秘密和策略，而营地则象征着复杂的环境和挑战。这个牌面提醒我们在处理复杂问题时要小心谨慎，避免不诚实的行为，并考虑到行动的后果。',4,'正位的宝剑七象征着策略和隐秘行动。它可能表示你需要在处理复杂问题时采取策略和隐秘的行动。这个牌面提醒我们在处理复杂问题时要小心谨慎，避免不诚实的行为，并考虑到行动的后果。通过谨慎的计划和策略，我们可以成功地解决问题。\r\n','逆位的宝剑七可能表示揭露和诚实。你可能需要面对过去的秘密和不诚实的行为，并承担相应的后果。这个牌面提醒我们要诚实和坦率，避免隐瞒和欺骗。通过诚实和坦率的态度，我们可以建立信任和改善人际关系。'),
(57,'宝剑八',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/宝剑八 Eight Of Swords.jpg','宝剑八代表着束缚和限制。这个牌面通常描绘一个被绑住的女人，周围环绕着剑，象征着被困住和无助的感觉。它提醒我们要意识到自我设限的思想和行为，努力打破束缚，寻找解决问题的方法。\r\n\r\n关键词\r\n束缚、限制、无助、困境\r\n\r\n象征意义\r\n宝剑八通常描绘一个被绑住的女人，周围环绕着剑，背景是阴云密布的天空。这个形象象征着束缚和限制。被绑住的女人代表着被困住和无助的感觉，而环绕的剑则象征着限制和困境。这个牌面提醒我们要意识到自我设限的思想和行为，努力打破束缚，寻找解决问题的方法。',4,'正位的宝剑八象征着束缚和限制。它可能表示你感到被困在某个困境中，无法找到解决问题的方法。这个牌面提醒我们要意识到自我设限的思想和行为，努力打破束缚，寻找解决问题的方法。通过积极的态度和勇敢的行动，我们可以克服困难，实现目标。\r\n','逆位的宝剑八可能表示解放和自由。你可能正在努力打破束缚，寻找解决问题的方法。这个牌面提醒我们要勇敢地面对挑战，努力实现自由和突破。通过积极的态度和勇敢的行动，我们可以克服困难，实现目标。'),
(58,'宝剑九',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/宝剑九 Nine Of Swords.jpg','宝剑九代表着焦虑和恐惧。这个牌面通常描绘一个坐在床上的人，双手捂住脸，背景是九把悬挂的剑，象征着内心的恐惧和不安。它提醒我们要面对内心的恐惧，努力寻找解决问题的方法，避免被焦虑和恐惧所控制。\r\n\r\n关键词\r\n焦虑、恐惧、失眠、内心冲突\r\n\r\n象征意义\r\n宝剑九通常描绘一个坐在床上的人，双手捂住脸，背景是九把悬挂的剑。这个形象象征着焦虑和恐惧。坐在床上的人代表着内心的恐惧和不安，而悬挂的剑则象征着内心的冲突和压力。这个牌面提醒我们要面对内心的恐惧，努力寻找解决问题的方法，避免被焦虑和恐惧所控制。',4,'正位的宝剑九象征着焦虑和恐惧。它可能表示你感到内心的恐惧和不安，无法入睡。这个牌面提醒我们要面对内心的恐惧，努力寻找解决问题的方法，避免被焦虑和恐惧所控制。通过积极的态度和勇敢的行动，我们可以克服内心的恐惧，实现内心的平静。\r\n','逆位的宝剑九可能表示解脱和安慰。你可能正在努力摆脱内心的恐惧，寻找解决问题的方法。这个牌面提醒我们要勇敢地面对挑战，努力实现内心的平静和安慰。通过积极的态度和勇敢的行动，我们可以克服内心的恐惧，实现内心的平静。'),
(59,'宝剑十',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/宝剑十 Ten Of Swords.jpg','宝剑十代表着结束和重生。这个牌面通常描绘一个被十把剑刺穿的躯体，背景是黎明的天空，象征着痛苦的结束和新的开始。它提醒我们在经历了痛苦和挫折之后，要勇敢地迎接新的开始，努力实现重生和成长。\r\n\r\n关键词\r\n结束、重生、痛苦、挫折\r\n\r\n象征意义\r\n宝剑十通常描绘一个被十把剑刺穿的躯体，背景是黎明的天空。这个形象象征着结束和重生。被刺穿的躯体代表着痛苦和挫折，而黎明的天空则象征着新的开始和希望。这个牌面提醒我们在经历了痛苦和挫折之后，要勇敢地迎接新的开始，努力实现重生和成长。',4,'正位的宝剑十象征着结束和重生。它可能表示你正在经历痛苦和挫折，但这些痛苦和挫折即将结束。这个牌面提醒我们在经历了痛苦和挫折之后，要勇敢地迎接新的开始，努力实现重生和成长。通过积极的态度和勇敢的行动，我们可以克服困难，实现目标。\r\n','逆位的宝剑十可能表示恢复和希望。你可能正在努力从痛苦和挫折中恢复过来，寻找新的希望和机会。这个牌面提醒我们要勇敢地面对挑战，努力实现恢复和重建。通过积极的态度和勇敢的行动，我们可以克服困难，实现目标。\r\n\r\n'),
(60,'宝剑侍从',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/宝剑侍从 Page Of Swords.jpg','宝剑侍从代表着好奇心和智力的探索。这个牌面通常描绘一个年轻人手持剑，象征着新的想法和学习的渴望。它提醒我们要保持开放的心态，勇敢地追求知识和真理，迎接新的挑战和机遇。\r\n\r\n关键词\r\n好奇心、智力、探索、学习\r\n\r\n象征意义\r\n宝剑侍从通常描绘一个年轻人手持剑，背景是风吹动的云。这个形象象征着好奇心和智力的探索。年轻人代表着新的想法和学习的渴望，而风吹动的云则象征着变化和不确定性。这个牌面提醒我们要保持开放的心态，勇敢地追求知识和真理，迎接新的挑战和机遇。',4,'正位的宝剑侍从象征着好奇心和智力的探索。它可能表示你正在追求新的想法和知识，渴望学习和成长。这个牌面提醒我们要保持开放的心态，勇敢地追求知识和真理，迎接新的挑战和机遇。通过积极的态度和勇敢的行动，我们可以实现智力的成长和个人的发展。\r\n','逆位的宝剑侍从可能表示不成熟和鲁莽。你可能在追求知识和真理的过程中遇到误解和延迟。这个牌面提醒我们要注意自己的行为和决定，避免鲁莽和不成熟。通过积极的态度和勇敢的行动，我们可以克服困难，实现智力的成长和个人的发展。'),
(61,'宝剑骑士',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/宝剑骑士 Knight Of Swords.jpg','宝剑骑士代表着行动和决心。这个牌面通常描绘一个骑士骑马冲锋，象征着快速的行动和坚定的决心。它提醒我们在追求目标时要保持专注和果断，勇敢地面对挑战和障碍。\r\n\r\n关键词\r\n行动、决心、专注、果断\r\n\r\n象征意义\r\n宝剑骑士通常描绘一个骑士骑马冲锋，背景是风吹动的云。这个形象象征着行动和决心。骑士代表着快速的行动和坚定的决心，而风吹动的云则象征着变化和不确定性。这个牌面提醒我们在追求目标时要保持专注和果断，勇敢地面对挑战和障碍。',4,'正位的宝剑骑士象征着行动和决心。它可能表示你正在快速地追求目标，充满了专注和果断。这个牌面提醒我们在追求目标时要保持专注和果断，勇敢地面对挑战和障碍。通过积极的态度和勇敢的行动，我们可以实现目标，克服困难。\r\n','逆位的宝剑骑士可能表示冲动和鲁莽。你可能在追求目标的过程中失去控制，导致延迟和挫折。这个牌面提醒我们要注意自己的行为和决定，避免冲动和鲁莽。通过积极的态度和勇敢的行动，我们可以克服困难，实现目标。'),
(62,'宝剑王后',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/宝剑王后 Queen Of Swords.jpg','宝剑王后代表着智慧和独立。这个牌面通常描绘一个坐在宝座上的女性，手持剑，象征着清晰的思维和独立的精神。它提醒我们要保持理智和客观，勇敢地面对挑战，做出明智的决定。\r\n\r\n关键词\r\n智慧、独立、理智、客观\r\n\r\n\r\n象征意义\r\n宝剑王后通常描绘一个坐在宝座上的女性，手持剑，背景是风吹动的云。这个形象象征着智慧和独立。坐在宝座上的女性代表着清晰的思维和独立的精神，而风吹动的云则象征着变化和不确定性。这个牌面提醒我们要保持理智和客观，勇敢地面对挑战，做出明智的决定。',4,'正位的宝剑王后象征着智慧和独立。它可能表示你正在运用清晰的思维和独立的精神，做出明智的决定。这个牌面提醒我们要保持理智和客观，勇敢地面对挑战，做出明智的决定。通过积极的态度和勇敢的行动，我们可以实现目标，克服困难。','逆位的宝剑王后可能表示冷漠和孤立。你可能在处理问题时表现出冷漠和偏见，导致误解和孤立。这个牌面提醒我们要注意自己的行为和决定，避免冷漠和偏见。通过积极的态度和勇敢的行动，我们可以克服困难，实现目标。'),
(63,'宝剑国王',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/宝剑国王 King Of Swords.jpg','宝剑国王代表着权威和理智。这个牌面通常描绘一个坐在宝座上的国王，手持剑，象征着清晰的思维和权威的决策。它提醒我们要保持理智和客观，勇敢地面对挑战，做出明智的决定。\r\n\r\n关键词\r\n权威、理智、决策、客观\r\n\r\n象征意义\r\n宝剑国王通常描绘一个坐在宝座上的国王，手持剑，背景是风吹动的云。这个形象象征着权威和理智。坐在宝座上的国王代表着清晰的思维和权威的决策，而风吹动的云则象征着变化和不确定性。这个牌面提醒我们要保持理智和客观，勇敢地面对挑战，做出明智的决定。',4,'正位的宝剑国王象征着权威和理智。它可能表示你正在运用清晰的思维和权威的决策，做出明智的决定。这个牌面提醒我们要保持理智和客观，勇敢地面对挑战，做出明智的决定。通过积极的态度和勇敢的行动，我们可以实现目标，克服困难。\r\n','逆位的宝剑国王可能表示专制和冷漠。你可能在处理问题时表现出专制和偏见，导致误解和孤立。这个牌面提醒我们要注意自己的行为和决定，避免专制和偏见。通过积极的态度和勇敢的行动，我们可以克服困难，实现目标。'),
(64,'钱币一',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/钱币一 Ace Of Pentacles.jpg','钱币一象征着新的物质机会和繁荣的开始。它代表着财富和物质上的新起点，提醒我们要抓住机会，实现财务上的增长和稳定。这张牌通常预示着新的财务机会和物质上的成功，提醒我们要努力实现目标。\r\n\r\n关键词\r\n新机会、繁荣、财富、物质成功、稳定\r\n\r\n象征意义\r\n钱币王牌通常描绘一只手从云中伸出，手中握着一枚钱币，象征着新的物质机会和繁荣的开始。钱币代表着财富和物质上的新起点，背景中的花园象征着繁荣和成长。这张牌提醒我们要抓住机会，实现财务上的增长和稳定。',5,'正位的钱币一象征着新的物质机会和繁荣的开始。它代表着财富和物质上的新起点，提醒我们要抓住机会，实现财务上的增长和稳定。这张牌通常预示着新的财务机会和物质上的成功，提醒我们要努力实现目标，迎接新的物质成就。\r\n','逆位的钱币一可能表示机会错失和财务不稳定。它可能预示着物质匮乏和延迟，提醒我们要面对财务上的挑战，抓住机会，避免失去。'),
(65,'钱币二',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/钱币二 Two Of Pentacles.jpg','钱币二象征着平衡和适应能力。它代表着在多重任务和责任之间找到平衡，提醒我们要灵活应对变化和挑战。这张牌通常预示着需要在不同的优先事项之间找到平衡，提醒我们要保持灵活和适应能力。\r\n\r\n关键词\r\n平衡、适应、灵活、管理、优先事项\r\n\r\n象征意义\r\n钱币二通常描绘一个人手持两个钱币，象征着平衡和适应能力。钱币代表着多重任务和责任，背景中的海浪象征着变化和挑战。这张牌提醒我们要在多重任务和责任之间找到平衡，灵活应对变化和挑战。',5,'正位的钱币二象征着平衡和适应能力。它代表着在多重任务和责任之间找到平衡，提醒我们要灵活应对变化和挑战。这张牌通常预示着需要在不同的优先事项之间找到平衡，提醒我们要保持灵活和适应能力，管理好时间和资源。\r\n','逆位的钱币二可能表示失衡和混乱。它可能预示着压力和优先事项不清，提醒我们要重新评估任务和责任，避免过度承诺，找到平衡。'),
(66,'钱币三',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/钱币三 Three Of Pentacles.jpg','钱币三象征着合作和团队工作。它代表着通过合作和共同努力实现目标，提醒我们要重视团队合作和集体智慧。这张牌通常预示着通过合作实现成功，提醒我们要与他人合作，共同实现目标。\r\n\r\n关键词\r\n合作、团队工作、集体智慧、共同努力、成功\r\n\r\n象征意义\r\n钱币三通常描绘三个人在建筑工地上合作，象征着合作和团队工作。钱币代表着集体智慧和共同努力，背景中的建筑象征着成功和成就。这张牌提醒我们要重视团队合作和集体智慧，通过合作实现成功。',5,'正位的钱币三象征着合作和团队工作。它代表着通过合作和共同努力实现目标，提醒我们要重视团队合作和集体智慧。这张牌通常预示着通过合作实现成功，提醒我们要与他人合作，共同实现目标，发挥集体的力量。','逆位的钱币三可能表示缺乏合作和团队不和。它可能预示着孤立和误解，提醒我们要改善沟通，促进合作，避免失败。'),
(67,'钱币四',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/钱币四 Four Of Pentacles.jpg','钱币四象征着控制和保守。它代表着对物质财富的紧握和对变化的抵制，提醒我们要平衡安全感和开放性。这张牌通常预示着对资源的控制和对变化的抵制，提醒我们要开放心态，避免过度保守。\r\n\r\n关键词\r\n控制、保守、安全、稳定、抵制变化\r\n\r\n象征意义\r\n钱币四通常描绘一个人紧握四个钱币，象征着控制和保守。钱币代表着物质财富和安全感，背景中的城市象征着稳定和抵制变化。这张牌提醒我们要平衡安全感和开放性，避免过度保守。',5,'正位的钱币四象征着控制和保守。它代表着对物质财富的紧握和对变化的抵制，提醒我们要平衡安全感和开放性。这张牌通常预示着对资源的控制和对变化的抵制，提醒我们要开放心态，避免过度保守，保持灵活性。\r\n','逆位的钱币四可能表示放手和开放。它可能预示着慷慨和变化，提醒我们要释放对物质的执着，接受变化，迎接新的机会。'),
(68,'钱币五',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/钱币五 Five Of Pentacles.jpg','钱币五象征着物质上的匮乏和困难。它代表着财务上的挑战和孤立，提醒我们要寻求帮助和支持。这张牌通常预示着物质上的困难和孤立，提醒我们要面对挑战，寻求支持，克服困难。\r\n\r\n关键词\r\n匮乏、困难、孤立、挑战、支持\r\n\r\n象征意义\r\n钱币五通常描绘两个人在雪地中行走，象征着物质上的匮乏和困难。钱币代表着物质财富的缺乏，背景中的教堂象征着希望和支持。这张牌提醒我们要寻求帮助和支持，克服物质上的困难。',5,'正位的钱币五象征着物质上的匮乏和困难。它代表着财务上的挑战和孤立，提醒我们要寻求帮助和支持。这张牌通常预示着物质上的困难和孤立，提醒我们要面对挑战，寻求支持，克服困难，找到希望。\r\n','逆位的钱币五可能表示恢复和希望。它可能预示着支持和改善，提醒我们要积极面对困难，寻求帮助，克服挑战，实现改善。'),
(69,'钱币六',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/钱币六 Six Of Pentacles.jpg','钱币六象征着慷慨和分享。它代表着给予和接受的平衡，提醒我们要慷慨地分享资源，帮助他人。这张牌通常预示着慷慨和分享的时刻，提醒我们要在给予和接受之间找到平衡。\r\n\r\n关键词\r\n慷慨、分享、平衡、给予、接受\r\n\r\n象征意义\r\n钱币六通常描绘一个富有的人给予乞丐钱币，象征着慷慨和分享。钱币代表着物质财富和给予，背景中的天平象征着平衡和公正。这张牌提醒我们要慷慨地分享资源，帮助他人，促进和谐和互助。',5,'正位的钱币六象征着慷慨和分享。它代表着给予和接受的平衡，提醒我们要慷慨地分享资源，帮助他人。这张牌通常预示着慷慨和分享的时刻，提醒我们要在给予和接受之间找到平衡，促进和谐和互助。\r\n','逆位的钱币六可能表示不平衡和自私。它可能预示着吝啬和依赖，提醒我们要避免自私，促进平衡和互助，避免失去。\r\n\r\n'),
(70,'钱币七',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/钱币七 Seven Of Pentacles.jpg','钱币七象征着耐心和评估。它代表着对努力成果的评估和对未来的规划，提醒我们要耐心等待结果，评估进展。这张牌通常预示着需要耐心和评估的时刻，提醒我们要评估努力的成果，规划未来的步骤。\r\n\r\n关键词\r\n耐心、评估、规划、等待、进展\r\n\r\n象征意义\r\n钱币七通常描绘一个人注视着生长中的植物，象征着耐心和评估。钱币代表着努力的成果和进展，背景中的植物象征着成长和未来的潜力。这张牌提醒我们要耐心等待结果，评估进展，规划未来的步骤。',5,'正位的钱币七象征着耐心和评估。它代表着对努力成果的评估和对未来的规划，提醒我们要耐心等待结果，评估进展。这张牌通常预示着需要耐心和评估的时刻，提醒我们要评估努力的成果，规划未来的步骤，确保成功。\r\n','逆位的钱币七可能表示焦虑和失望。它可能预示着缺乏进展和浪费，提醒我们要重新评估努力，避免急躁，找到改进的方法。'),
(71,'钱币八',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/钱币八 Eight Of Pentacles.jpg','钱币八象征着勤奋和技能的提升。它代表着通过努力和专注提高技能和成就，提醒我们要专注于工作和学习。这张牌通常预示着通过努力实现进步，提醒我们要专注于技能的提升和目标的实现。\r\n\r\n关键词\r\n勤奋、技能提升、专注、努力、成就\r\n\r\n象征意义\r\n钱币八通常描绘一个工匠专注于雕刻钱币，象征着勤奋和技能的提升。钱币代表着努力的成果和成就，背景中的工作台象征着专注和努力。这张牌提醒我们要专注于工作和学习，提高技能，实现目标。',5,'正位的钱币八象征着勤奋和技能的提升。它代表着通过努力和专注提高技能和成就，提醒我们要专注于工作和学习。这张牌通常预示着通过努力实现进步，提醒我们要专注于技能的提升和目标的实现，取得成就。\r\n','逆位的钱币八可能表示懒惰和技能不足。它可能预示着分心和失败，提醒我们要克服懒惰，专注于技能的提升，避免停滞。'),
(72,'钱币九',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/钱币九 Nine Of Pentacles.jpg','钱币九象征着独立和物质上的成就。它代表着通过努力实现的物质财富和独立，提醒我们要珍惜独立和成就。这张牌通常预示着物质上的成功和独立，提醒我们要享受努力的成果，珍惜独立。\r\n\r\n关键词\r\n独立、成就、物质财富、享受、成功\r\n\r\n象征意义\r\n钱币九通常描绘一个人在花园中享受丰收，象征着独立和物质上的成就。钱币代表着物质财富和成就，背景中的花园象征着享受和成功。这张牌提醒我们要珍惜独立和成就，享受努力的成果。',5,'正位的钱币九象征着独立和物质上的成就。它代表着通过努力实现的物质财富和独立，提醒我们要珍惜独立和成就。这张牌通常预示着物质上的成功和独立，提醒我们要享受努力的成果，珍惜独立，保持自信。\r\n','逆位的钱币九可能表示依赖和物质匮乏。它可能预示着孤独和失去，提醒我们要克服依赖，追求独立，避免失败。'),
(73,'钱币十',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/钱币十 Ten Of Pentacles.jpg','钱币十象征着家庭的繁荣和物质上的圆满。它代表着通过努力实现的物质财富和家庭的幸福，提醒我们要珍惜家庭和成就。这张牌通常预示着物质上的成功和家庭的繁荣，提醒我们要享受努力的成果，珍惜家庭的幸福。\r\n\r\n关键词\r\n家庭繁荣、物质圆满、成就、幸福、成功\r\n\r\n象征意义\r\n钱币十通常描绘一个家庭在庭院中享受丰收，象征着家庭的繁荣和物质上的圆满。钱币代表着物质财富和成就，背景中的庭院象征着家庭的幸福和成功。这张牌提醒我们要珍惜家庭和成就，享受努力的成果，保持和谐。',5,'正位的钱币十象征着家庭的繁荣和物质上的圆满。它代表着通过努力实现的物质财富和家庭的幸福，提醒我们要珍惜家庭和成就。这张牌通常预示着物质上的成功和家庭的繁荣，提醒我们要享受努力的成果，珍惜家庭的幸福，保持和谐。\r\n','逆位的钱币十可能表示家庭不和和物质匮乏。它可能预示着失去和失败，提醒我们要克服家庭的挑战，追求和谐，避免孤独。'),
(74,'钱币侍从',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/钱币侍从 Page Of Pentacles.jpg','钱币侍从象征着新的物质机会和学习的开始。它代表着对物质世界的好奇和对知识的渴望，提醒我们要开放心态，迎接新的学习和成长。这张牌通常预示着新的学习机会和物质上的新起点，提醒我们要专注于学习和成长。\r\n\r\n关键词\r\n新机会、学习、成长、好奇、物质世界\r\n\r\n象征意义\r\n钱币侍从通常描绘一个年轻人手持钱币，象征着新的物质机会和学习的开始。钱币代表着物质世界和学习的机会，背景中的田野象征着成长和潜力。这张牌提醒我们要开放心态，迎接新的学习和成长。',5,'正位的钱币侍从象征着新的物质机会和学习的开始。它代表着对物质世界的好奇和对知识的渴望，提醒我们要开放心态，迎接新的学习和成长。这张牌通常预示着新的学习机会和物质上的新起点，提醒我们要专注于学习和成长，取得进步。\r\n','逆位的钱币侍从可能表示懒惰和缺乏动力。它可能预示着分心和失败，提醒我们要克服懒惰，专注于学习和成长，避免停滞。'),
(75,'钱币骑士',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/钱币骑士 Knight Of Pentacles.jpg','钱币骑士象征着勤奋和责任感。它代表着对物质世界的专注和对目标的坚定，提醒我们要努力工作，实现目标。这张牌通常预示着通过努力实现目标，提醒我们要专注于工作和责任，保持坚定。\r\n\r\n关键词\r\n勤奋、责任、专注、努力、坚定\r\n\r\n象征意义\r\n钱币骑士通常描绘一个骑士手持钱币，象征着勤奋和责任感。钱币代表着物质世界和目标，背景中的田野象征着努力和成长。这张牌提醒我们要专注于工作和责任，实现目标。',5,'正位的钱币骑士象征着勤奋和责任感。它代表着对物质世界的专注和对目标的坚定，提醒我们要努力工作，实现目标。这张牌通常预示着通过努力实现目标，提醒我们要专注于工作和责任，保持坚定，取得成功。\r\n','逆位的钱币骑士可能表示懒惰和缺乏动力。它可能预示着分心和失败，提醒我们要克服懒惰，专注于工作和责任，避免停滞。'),
(76,'钱币王后',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/钱币王后 Queen Of Pentacles.jpg','钱币王后象征着物质上的富足和关怀。它代表着对物质世界的掌控和对他人的关心，提醒我们要珍惜物质财富，关心他人。这张牌通常预示着物质上的成功和关怀，提醒我们要珍惜物质财富，关心他人。\r\n\r\n关键词\r\n富足、关怀、掌控、物质世界、成功\r\n\r\n象征意义\r\n钱币王后通常描绘一个皇后手持钱币，象征着物质上的富足和关怀。钱币代表着物质世界和成功，背景中的花园象征着富足和关怀。这张牌提醒我们要珍惜物质财富，关心他人，保持和谐。',5,'正位的钱币王后象征着物质上的富足和关怀。它代表着对物质世界的掌控和对他人的关心，提醒我们要珍惜物质财富，关心他人。这张牌通常预示着物质上的成功和关怀，提醒我们要珍惜物质财富，关心他人，保持和谐。\r\n','逆位的钱币王后可能表示物质匮乏和冷漠。它可能预示着失去和失败，提醒我们要克服物质上的挑战，关心他人，避免孤独。'),
(77,'钱币国王',0,'https://tarot-1409233212.cos.ap-guangzhou.myqcloud.com/tarot_images/tarot_card/钱币国王 King Of Pentacles.jpg','钱币国王象征着物质上的成功和稳定。它代表着对物质世界的掌控和对成功的追求，提醒我们要珍惜物质财富，实现目标。这张牌通常预示着物质上的成功和稳定，提醒我们要珍惜物质财富，实现目标。\r\n\r\n关键词\r\n成功、稳定、掌控、物质世界、目标\r\n\r\n象征意义\r\n钱币国王通常描绘一个国王手持钱币，象征着物质上的成功和稳定。钱币代表着物质世界和目标，背景中的王座象征着掌控和成功。这张牌提醒我们要珍惜物质财富，实现目标，保持和谐。',5,'正位的钱币国王象征着物质上的成功和稳定。它代表着对物质世界的掌控和对成功的追求，提醒我们要珍惜物质财富，实现目标。这张牌通常预示着物质上的成功和稳定，提醒我们要珍惜物质财富，实现目标，保持和谐。\r\n','逆位的钱币国王可能表示物质匮乏和失去。它可能预示着失败和孤独，提醒我们要克服物质上的挑战，追求成功，避免动荡。');

/*Table structure for table `tarot_interpretation` */

DROP TABLE IF EXISTS `tarot_interpretation`;

CREATE TABLE `tarot_interpretation` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '解读ID（主键）',
  `tarot_record_id` int unsigned NOT NULL COMMENT '占卜记录ID（关联tarot_record表）',
  `summary` varchar(200) NOT NULL COMMENT '整体总结',
  `detail` text NOT NULL COMMENT '详细解读内容',
  `advice` varchar(200) DEFAULT '' COMMENT '行动建议',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '解读生成时间',
  PRIMARY KEY (`id`),
  KEY `fk_analysis_spread` (`tarot_record_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='占卜解读表';

/*Data for the table `tarot_interpretation` */

(1,1,'本次恋人复合牌阵整体运势分析：双方关系存在复合契机，但需理性沟通','【你的现状】宝剑国王正位：代表你目前理性冷静，对关系有清晰认知；【TA的现状】星币骑士逆位：对方目前状态浮躁，缺乏行动力；【最后结果】宝剑四正位：关系需要时间沉淀，不宜急于求成','1. 保持理性，给彼此足够的冷静期；2. 避免情绪化沟通，聚焦问题本质；3. 尊重对方节奏，不要过度施压','2026-04-01 14:54:59'),
(2,1,'【三牌阵】1.我三个月内能谈恋爱吗?','【牌1】愚人（逆位）\n鲁莽、缺乏计划\n\n【牌2】权杖王后（正位）\n自信、独立、决心\n\n【牌3】权杖五（正位）\n竞争、冲突、分歧\n\n','✨ 塔罗是指引，真正的力量永远来自你自己。','2026-04-01 17:19:07'),
