/*Table structure for table `tarot_record_collection` */

DROP TABLE IF EXISTS `tarot_record_collection`;

CREATE TABLE `tarot_record_collection` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '收藏ID（主键）',
  `user_id` bigint unsigned NOT NULL COMMENT '用户ID（关联userinfo表）',
  `target_id` int unsigned NOT NULL COMMENT '收藏目标ID',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '收藏时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_target` (`user_id`,`target_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户收藏表';

